(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["3-3"] = [{"a": [96, 97], "v": 2, "p": 724, "ev": 2, "ep": 746, "sid": 926, "t": "قوله: (إن أول بيت وضع للناس للذي ببكة مباركا وهدى للعالمين (96) فيه آيات بينات مقام إبراهيم ومن دخله كان آمنا ولله على الناس حج البيت من استطاع إليه سبيلا ومن كفر فإن الله غني عن العالمين (97)\n⟦2:725⟧\nقيل: بكة هي المسجد، ومكة الحرم، وقيل: بكة هي البيت.\nوقيل: هي بطن الحرم وقال مجاهد: هما واحد\n⟦2:726⟧\nكقوله سبد رأسه وسمده، أي حلقه، وضرب لازم ولازب.\nوأصل بكة من التباك أي التزاحم، وذلك اعتبارا بازدحامهم\nلقصده، والطواف به، وقيل: لبكه أعناق الجبابرة إذا ألحدوا\n⟦2:727⟧\nفيه، ومكة من أمتك الفصيل ما في الضرع، كأنه يجمع أهل\nالآفاق ويؤلفهم، ولذلك سميت أم الزحم.\nوالبركة: ثبوت. الخير في الشيء ثبوت الماء في البركة.\nوسميت البركة لثبوت الماء، وأصل الكلمة البرك، وبرك البعير ألقى بركه وبركاء\n⟦2:728⟧\nالقتال ملازمته، وتبارك الله تخصص بلزوم فعل الخيرات.\nواختلف في بناء البيت، فقال مجاهد وقتادة: هو أول بيت بني\nفي الأرض،\n⟦2:729⟧\nوقال علي: أول بيت وضع للعبادة، وهذا الاختلاف لاختلاف\nالتقديرين في الآية، لأنه على الثاني: إن أول بيت وضع للناس\nمباركا وهدى للعالمين للذي ببكة، ثم اختلفوا في معنى\n(أول). فمنهم من اعتبر ذلك بالشرف والمنزلة، فكأنه قيل:\nأشرف بيت، وعلى ذلك قال مجاهد: هو كقوله: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ﴾⟪3:110⟫. ومنهم من اعتبر أوليته بالزمان.\nقال: أول\n⟦2:730⟧\nبيت بعد الطوفان، وهو الذي قال: ﴿وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ﴾⟪2:127⟫. ومنهم من قال: أول موضع اتخذته الملائكة قبلة\n⟦2:731⟧\nفي الأرض، وروى في ذلك أخبارا، وهذا لا يقتضيه الظاهر.\nلأنه قال: ﴿وُضِعَ لِلنَّاسِ﴾⟪3:96⟫، فخص بالناس، وعلى هذا اعتبروا\n(العتيق) في قوله: ﴿بِٱلۡبَيۡتِ ٱلۡعَتِيقِ﴾⟪22:29⟫، ونبه بقوله:\nمباركا، أن فيه ثبوت الخير والهداية، وأبهم هاهنا، ثم فسره بما\nبعده، واختلفوا في المقام، والأمن، فمنهم من حمل المقام على\nالمحسوس)، وقال: إنه أثر قدم إبراهيم على الحجر الصلد.\n⟦2:732⟧\nومنهم من حمله على الأحكام، وقال: هو موضع الطواف\nوالسعي وسائر أركان الحج، ولهذا قال: (آيات)، ثم فسره\nبمقام وإن كان لفظه مفردا، ومفهم من قال: الآيات هي\nالمعاني المضمنة فيه التي يستدل بها العارف، والمقام ما تخصص\nبه إبراهيم من الخلة التي اكتسبها ببذل النفس والمال والولد.\nفعلى هذا قوله: ﴿وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾⟪3:97⟫ من العقوبة، وقال\n⟦2:733⟧\nبعض الصالحين: كنت أطوف فخطر لي قوله: ﴿وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾⟪3:97⟫\nترى من أي شيء يأمن؟ فسمعت هاتفا يقول: من النار.\nوقيل (كان آمنا) من بلايا الدنيا وأعراضها التي\nتصيب من قال فيهم: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُعَذِّبَهُم بِهَا فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا﴾⟪9:55⟫.\nومنهم من حمل: ﴿وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾⟪3:97⟫ على الحكم.\nثم اختلفوا. فمنهم من جعله خبرا، وقال: معناه أن من\nدخله كان آمنا، وذلك كان في الجاهلية، لأنه لم يكن يتعرض\n⟦2:734⟧\nلجان يلتجئ إلى الحرم بوجه حتى يخرج، وقال الحسن\nوالأصم: من دخله يأمن الاصطلام، ومنهم من حمل ذلك\nعلى التعبد، أي في حكم الله، وإن كان في نفسه وجلا، كقولك:\nهذا مباح، وهذا محظور، فعلى هذا من جعل الضمير في قوله:\n﴿وَمَن دَخَلَهُۥ﴾⟪3:97⟫ للبيت قال: لا يتعرض له بوجه إلى أن يخرج، ومن جعله\nللحرم فمنهم من قال: من قتل في غير الحرم ثم دخله لم يقتص منه\nإلى أن يخرج، لكن لا يبايع ولا يواكل حتى يضطر إلى الخروج.\nوقال الحسن: يقتص من الكل، وهذا كان حكما في الجاهلية.\nولم يختلفوا أنه إذا جنى في الحرم كان مأخوذا بجنايته، وعلى\n⟦2:735⟧\nقوله: ﴿وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ﴾⟪3:97⟫ يحمل قوله: ﴿أَوَلَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا﴾⟪29:67⟫، وقوله: ﴿وَإِذۡ جَعَلۡنَا ٱلۡبَيۡتَ مَثَابَةٗ لِّلنَّاسِ وَأَمۡنٗا﴾⟪2:125⟫،\n⟦2:736⟧\nوقوله: ﴿ٱجۡعَلۡ هَٰذَا ٱلۡبَلَدَ ءَامِنٗا﴾⟪14:35⟫، وقرئ ﴿ءَايَةِۭ بَيِّنَةٖۗ﴾.\nوكأن قارئه نظر إلى لفظ ما أبدل منه، وهو مقام إبراهيم، فلما كان\nمفردا جعل الآية مفردة، والصحيح ما عليه الكافة، فالمقام\n⟦2:737⟧\nمصدر، ويتناول الواحد والجمع، فإذا اعتبر بالمحسوس فهي\nالمناسك، وإذا اعتبر بالمعقول فأفعال إبراهيم المتقدم ذكرها.\nقوله: (ولله على الناس حج البيت من استطاع إليه سبيلا ومن كفر فإن الله غني عن العالمين (97)\nالسبيل: إمكان الوصول إليه، كقوله تعالى: ﴿فَهَلۡ إِلَىٰ خُرُوجٖ مِّن سَبِيلٖ﴾⟪40:11⟫ والاستطاعة: استدعاء الطاعة، كان النفس بالقدرة تستدير طاعة الشيء لها، والقدرة والطاقة، والاستطاعة والجهد والوسع متقاربة، وقد\n⟦2:738⟧\nتقدم ذلك، وقولهم: لا يستطيع كذا. تارة يقال لنفي القدرة.\nوتارة لنفي الخفة، فإن قوله: ﴿لَا يَسۡتَطِيعُونَ سَمۡعًا﴾⟪18:101⟫ أي\nيستثقلونه، لا لأنهم لا يقدرون عليه، وتمام استطاعة العبادة\n⟦2:739⟧\nثلاث: الأول: استطاعة نفسية، وهي المعرفة بها، أو التمكن\nمن معرفتها.\nوالثاني: استطاعة بدنية، وهي أن يكون صحيح البدن قادرا على إقامتها. والثالث: استطاعة من خارج، وهي وجود الآلة التي بها يتمكن من فعلها، ومتى اجتمعت الثلاثة فقد حصل تمام الاستطاعة.\nوإلا فالاستطاعة معدومة أو قاصرة.\nوقول النبي - صلى الله عليه وسلم -: \"الاستطاعة: الزاد والراحلة\"\n⟦2:740⟧\nمتناولة للخارجة دون البدنية والنفسية، وخصها - صلى الله عليه وسلم - بالذكر لما كان معلوما عندهم أن بافتقاد الأوليين لا يكلف.\nوكأن القوم قد شكوا أن الفقير الذي تبعد مسافته، ولا يتمكن من زاد وراحلة هل يلزمه الحج؟ فراجعوه، فبين - صلى الله عليه وسلم - لهم ذلك، ولم تتناول الآية العبد، لأنه لا ملك له في قول جل الفقهاء، وفي قول بعضهم سيده أولى بما في يده، وله أن يمنعه باتفاق، وكذا المرأة إذا لم يكن\nلها محرم، هذا قول الفقهاء، فأما الصوفية فقد قالوا: الزاد\n⟦2:741⟧\nالتقوى، لقوله تعالى: ﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ﴾⟪2:197⟫\nوالراحلة صحة البدن، وقد عبر عن البدن بذلك في قوله: \"إن\nالمنبت لا أرضا قطع ولا ظهرا أبقى\".\nوقال بعضهم: فيه مع إرادة هذا المعنى تنبيه على معنى أبلغ من ذلك البيت جنة المأوى،\n⟦2:742⟧\nلقوله: ﴿ٱبۡنِ لِي عِندَكَ بَيۡتٗا فِي ٱلۡجَنَّةِ﴾⟪66:11⟫ ولما لم يكن للإنسان\nسبيل إلى ذلك إلا بحسن، عبادته صار ذلك حقا على الناس.\nولذلك أكد لفظه، وخصه بما لم يخص به شيئا من العبادات.\nفقال ﴿وَلِلَّهِ عَلَى ٱلنَّاسِ﴾⟪3:97⟫.\nوقال بعض الصوفية: في الحج إشارات اقتضت تأكيد لفظ الأمر به.\nوذاك أن في العقد به إشارة إلى معاقدة الولاء المعني بقوله: ﴿ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ﴾⟪2:257⟫، وبالتلبية إلى الإجابة له فيما دعا إليه، وبالتجرد إلى التجرد من\nالدنيا، وأنه عاد كما خرج من بطن أمه، وبالوقوف إلى الوقوف\nببابه، وبالسعي إلى السعي إليه، وبالطواف إلى محل القربة\nمنه، قال: ولذلك حق على المسلم أن يتغير حاله بعد حجه\nعما كان عليه قبل، ولهذا قال - صلى الله عليه وسلم -: \" من حج فلم يفسق ولم يرفث كان كيوم ولدته أمه \"، يعني لم يفسق ولم يرفث بعد رجوعه من\n⟦2:743⟧\nالحج، ولم يعن في الحج، فإن ذلك مدلول عليه بقوله: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ﴾⟪2:197⟫.\nوقوله: ﴿وَمَن كَفَرَ﴾⟪3:97⟫ قال ابن عباس: من كفر بوجوب الحج عليه، وعلى هذا ما ورد أن رجلا سأل النبي - صلى الله عليه وسلم - عن ذلك فقال: \"من إن حج لم يرج ثوابه، وإن جلس لم يخف عقابه \"\nوأما من تركه ممن يري وجوبه لم يكن كافرا\n⟦2:744⟧\nوإن كان عاصيا، وقيل: الكفر كفران: كفر تام، وهو إنكار\nالوحدانية، أو ما يجري مجراه، وكفر ناقص، وهو الإخلال\nببعض العبادات، التي هي أركان الدين: كالصلاة والزكاة والحج.\nولهذا قال - صلى الله عليه وسلم -: \"من ترك الصلاة فقد كفر\"،\n⟦2:745⟧\nوقال - صلى الله عليه وسلم -: \"من مات وعليه حج الإسلام فلا عليه أن يموت إن شاء يهوديا وإن شاء نصرانيا\".\nوإنما قال: ﴿غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ﴾⟪3:97⟫ تنبيها أن قوله: ﴿وَلِلَّهِ عَلَى ٱلنَّاسِ﴾⟪3:97⟫ ليس لحاجة به، وإنما ذلك\n⟦2:746⟧\nلحاجتهم ونفعهم، إذ هو تعالى الغني المطلق، وغيره وإن استغنى عن شيء\nما فغير غني عنه تعالى في شيء من الأحوال، وهو القائم على كل شيء."}, {"a": [98], "v": 2, "p": 746, "ev": 2, "ep": 747, "sid": 948, "t": "قوله تعالى: (قل يا أهل الكتاب لم تكفرون بآيات الله والله شهيد على ما تعملون (98)\nالذي اقتضى مخاطبتهم بهذا إنكارهم نبوة محمد، ووجوب الحج، والآيات المقتضية لذلك من الكتب المتقدمة ومن القرآن، وبين بقوله: ﴿وَٱللَّهُ شَهِيدٌ عَلَىٰ مَا تَعۡمَلُونَ﴾⟪3:98⟫ أنكم تسترون ما لا يستتر، إذ هو لا يخفى عليه خافية.\nإن قيل: لم قال في موضع: ﴿يَٰٓأَهۡلَ ٱلۡكِتَٰبِ﴾⟪3:98⟫ وهاهنا قال: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ﴾⟪3:98⟫؟\nقيل: الأول استدعاء إلى الحق فجعل خطابهم منه استلانة للقول، ليكونوا أقرب إلى انقيادهم، وهاهنا لما قصد إلى الغض منهم ذكر (قل) تنبيها\nأنهم غير مستأهلين أن يخاطبهم بنفسه تعالى، وإن كان كلا\n⟦2:747⟧\nالخطابين موصلا على لسان النبي - صلى الله عليه وسلم -.\nإن قيل: لم صار أهل الكتاب يطلق في القرآن تارة على سبيل الذم، وتارة على سبيل المدح، ولا نجري قولنا: أهل القرآن وأهل السنة هذا المجرى؟ قيل: الكتاب لما كان قد يراد به ما افتعلوه دون ما أنزل الله نحو: ﴿لِّلَّذِينَ يَكۡتُبُونَ ٱلۡكِتَٰبَ بِأَيۡدِيهِمۡ﴾⟪2:79⟫، وقد يراد به ما أنزل الله تعالى، فيكون على سبيل الذم لأهل الكتاب، وقد يراد به ما أنزله الله، ويكون على سبيل التهكم، نحو قوله:\n﴿ذُقۡ إِنَّكَ أَنتَ ٱلۡعَزِيزُ ٱلۡكَرِيمُ﴾⟪44:49⟫ فعلى هذا لو قيل: أهل القرآن\nوأهل السنة على سبيل الذم والتهكم لجاز، وقوله: (لم) وإن كان أصله\nاستفهاما فالقصد به هاهنا الإنكار والتنبيه؛ أن لا جواب لهم ولا عذر."}, {"a": [99], "v": 2, "p": 748, "ev": 2, "ep": 751, "sid": 950, "t": "قوله تعالى: (قل يا أهل الكتاب لم تصدون عن سبيل الله من آمن تبغونها عوجا وأنتم شهداء وما الله بغافل عما تعملون (99).\nيقال: بغيته كذا أي طلبته له، وأبغيته أعنته على بغائه، نحو لمسته كذا\nوألمسته، وحملته كذا وأحملته، والعوج ما يدرك بالفكر من الاعوجاج.\nوالعوج ما يدرك بالطرف، وقوله: ﴿لَّا تَرَىٰ فِيهَا عِوَجٗا وَلَآ أَمۡتٗا﴾⟪20:107⟫.\nيعني الظلم وما يجري مجراه مما يكون في الدنيا،\n⟦2:750⟧\nومعناه لا تصدوا المؤمنين طالبين لطريقهم الإعوجاج.\nوقوله: ﴿وَأَنتُمۡ شُهَدَآءُۗ﴾⟪3:99⟫ الشهادة تارة بالعقل نحو ﴿أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ﴾⟪50:37⟫\nأي عارف بعقله، وتارة بالعقد، نحو قوله: ﴿فَٱشۡهَدُواْ وَأَنَا۠ مَعَكُم مِّنَ ٱلشَّٰهِدِينَ﴾⟪3:81⟫ وتارة بإقامة ذلك، وقد فسر الآية\n⟦2:751⟧\nبثلاثتها؛ فقد قيل: وأنتم عقلاء تعرفون ذلك بعقولكم.\nقيل: وأنتم قد أخذ عليكم العهد بقوله: ﴿وَإِذۡ أَخَذَ ٱللَّهُ مِيثَٰقَ﴾\nقيل: وأنتم شهدتم نبوته قبل بعثته، وكل ذلك مراد فلا تنافي بينها."}, {"a": [100], "v": 2, "p": 751, "ev": 2, "ep": 752, "sid": 952, "t": "قوله تعالى: (يا أيها الذين آمنوا إن تطيعوا فريقا من الذين أوتوا الكتاب يردوكم بعد إيمانكم كافرين (100)\nقال السدي: نزلت في قوم من اليهود، سعوا بين أوس وخزرج بالفساد، وذكروهم من الأحقاد والأوتار)، فأنزل الله تعالى ذلك، وتلاه عليهم النبي - صلى الله عليه وسلم - فأحجموا عما هموا\n⟦2:752⟧\nبه، والطاعة: بذل الانقياد والإجابة نحوها، غير أن الإجابة قد\nتكون بالقول مرة وبالفعل مرة، ومتى كانت بالفعل فهي موافقة الداعي\nدون الانقياد، ولهذا يقال: أجاب الله عبده، ولا يقال أطاعه، وإنما\nخص فريقا منهم لئلا يدخل فيه من قال فيهم:. ﴿مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ أُمَّةٞ قَآئِمَةٞ يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ﴾⟪3:113⟫، وعنى بالإيمان هاهنا الخوض فيه\nدون استكماله المعني بقوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾⟪8:2⟫، فإن من بلغ هذه المنزلة فمحال أن يرد على عقبه، ولهذا\nقيل: ما رجع من رجع إلا من الطريق."}, {"a": [101], "v": 2, "p": 753, "ev": 2, "ep": 756, "sid": 954, "t": "قوله تعالى: (وكيف تكفرون وأنتم تتلى عليكم آيات الله وفيكم رسوله ومن يعتصم بالله فقد هدي إلى صراط مستقيم (101)\nالعصم والعصب يتقاربان، لكن العصم أبلغ، فإن معه الشد إمساكا، والأعصم: الوعل المعتصم بالجبل، والعصام على بناء الزمام والسخاب، وجمعه عصم، واعتصمت به واعتصمته نحو تعلقت به وتعلقته،\n⟦2:754⟧\nوالعصمة من الله على ثلاثة أضرب: عامة لكل مكلف، وهي ما\nيفيض له من العقل، وهدايته بالأمر والنهي والوعد والوعيد.\nوالثانية : لمن اهتدى بالأولى، وهي التي يرغب كل مؤمن أن\nيجعل الله له منها حظا. وإياها قصد بقوله: ﴿وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ﴾⟪29:69⟫.\nوالثالثة: للأنبياء وكيفيتها مختلف فيها.\nوالاعتصام، والتفويض، والتوكل، والإسلام - أي الاستسلام -\nمترتب بعضها على بعض، فالاعتصام قبل التفويض.\nوالتفويض قبل التوكل، لأن معنى فوضت أمري إلى فلان، أي\nجعلت له الفوض فيه، ومعنى توكلت عليه: اعتزلت، وجعلته\nالمعتمد، وأما الإسلام فغايته ما كان من إبراهيم عليه السلام.\nحيث قال: ﴿أَسۡلَمۡتُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾⟪2:131⟫، ولكون الاعتصام\nأول منزلة من هذه المنازل.\nقال بعض الصوفية: الاعتصام\n⟦2:755⟧\nللمحجوبين (1)، فأما أهل الحقائق فهم في القبضة (2)، واستبعد\n⟦2:756⟧\nالله تحولهم مع ظهوو الآيات التي هي المعجزات العقلية، وكون الرسول\nالشاهد فيما بينهم الذي يظهر من العجزات المحسوسة.\nوقيل: معنى قوله: ﴿وَفِيكُمۡ رَسُولُهُۥۗ﴾⟪3:101⟫ أي دلائله لا ذاته، فعلى هذا خطاب لمن في زمانه، ولمن بعده.\nوقوله: ﴿فَقَدۡ هُدِيَ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ﴾⟪3:101⟫ أي الطريق المسئول\nأن يهدينا إليه في قوله: ﴿ٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ﴾⟪1:6⟫.\nوالمدعو إليه بقوله: ﴿وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ﴾⟪6:153⟫.\nوالمأمور به في قوله: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ﴾⟪16:125⟫."}, {"a": [102], "v": 2, "p": 756, "ev": 2, "ep": 764, "sid": 957, "t": "قوله: (يا أيها الذين آمنوا اتقوا الله حق تقاته ولا تموتن إلا وأنتم مسلمون (102)\n⟦2:757⟧\nالتقوى: أن تجعل بينك وبين المعاصي ما يصير واقيا\nلك عن تعاطيها، فتصير واقيا لك في الآخرة عن العذاب.\nوقال بعض الناس: التقوى من ثلاثة أوجه: تقوى من غرور\nالدنيا، والتقوى من النفس، والتقوى من الله.\nوكل واحد منها على ثلاث منازل:\nأما التقوى من الدنيا فأن تتقي محرماتها، ثم شبهاتها.\nثم الزهد في مباحاتها.\nوأما التقوى من النفس فأن تتقي أولا عقوبته.\nثم استدراجه نحو: أن يملي للعبد ويوسع عليه فيغتر به.\nثم حجابه، نحو: أن يسأله العبد\n⟦2:758⟧\nفتتباطأ إجابته فيعير ذلك قلبه، فمن استكمل هذه المنازل فقد اتقى الله حق.\nتقاته، وحرر ذلك بعض الصوفية على وجه آخر.\nوقال: التقوى على ثلاث منازل: تقوى العقوبة بالصبر عن المعاصي.\nوإياه قصد بقوله: ﴿وَٱتَّقُواْ ٱلنَّارَ ٱلَّتِيٓ أُعِدَّتۡ لِلۡكَٰفِرِينَ﴾⟪3:131⟫.\nوتقواه بشكر آلائه ، وإياه قصد بقوله: ﴿ٱتَّقُواْ رَبَّكُمُ﴾ خص لفظ الرب المنبئ عن تربيته إياه ونعمته عليه، وتقواه برؤية وحدانيته من غير تلفت ثواب أو عقاب، وإياه قصد بقوله: ﴿ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ﴾⟪3:102⟫ قال: ولهذا حيث ما ذكر (اتقوا الله) خص المؤمنين بالمخاطبة، وحيثما ذكر (اتقوا ربكم) خص الناس الذي هو أعم اللفظتين.\nوتقسيم التقوى على ئلاث منازل هو على حسب الظالم\n⟦2:759⟧\nوالمقتصد والسابق، وقوله: ﴿حَقَّ تُقَاتِهِۦ﴾⟪3:102⟫ حث أن يبلغ\nالإنسان في ذلك مبلغ السابقين، قال عبد الله والحسن وقتادة: هو\nأن يطاع فلا يعصى، ويذكر فلا ينسى، ويشكر فلا يكفر.\n⟦2:760⟧\nوقال قتادة والربيع: الآية منسوخة بقوله: ﴿فَٱتَّقُواْ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ﴾⟪64:16⟫\nوقال غيرهما: بل معناهما واحد، فإن حق التقوى\nهو التقوى على حسب الاستطاعة، واستدل بما روى\n⟦2:761⟧\nمعاذ قال: أردفني رسول الله - صلى الله عليه وسلم -، وقال: \"هل تدري حق الله على العباد؟\n\" قلت: الله أعلم ورسوله، فقال: \"أن يعبدوه ولا يشركوا به شيئا\".\nثم قرأ: ﴿ٱتَّقُواْ ٱللَّهَ حَقَّ تُقَاتِهِۦ﴾⟪3:102⟫،\n⟦2:762⟧\nومن قال: هذا منسوخ تصور من قوله: ﴿حَقَّ تُقَاتِهِۦ﴾⟪3:102⟫ غاية الجهد من\nالعبد، وإن (ما استطعتم) هو قدر العفو، فصار مقتضى ما استطعتم\nأخف من مقتضى حق تقاته، واستقبح أبو علي الجبائي قول من\nقال: الآية منسوخة، وقال: هذا جهل، لأنه لا يجوز أن يبيح الله\nللناس أن يفعلوا بعض المعاصي وهذا تصور له وقع من قلة التثبت.\nفقد علم أن فعل ما حظر الله في الشرع معصية ما دام الحظر قائما.\nكتحريم الأكل والجماع بعد النوم في الصوم، ثم لما زال الحظر زال\nكونه معصية. فكذا تقوى الله بغاية ما بلغه الجهد لا يمنع أن\n⟦2:763⟧\nتوجب في وقت، فيكون تركها معصية، ثم يقتصر من الناس علي\nمقدار الوسع، فلا يكون ترك الجهد معصية.\nوقوله: ﴿وَلَا تَمُوتُنَّ﴾⟪3:102⟫ حث على الاستسلام قبل الموت.\nوإن كان لفظه نهيا عن الموت كقولهم: لا أرينك هاهنا.\nإن قيل: هل بين قولك: لا تموتن إلا مسلما، وقولك: إلا وأنت مسلم فرق؟\nقيل: قولك مسلما يقتضي ظاهره أن يكون الإسلام مقترنا به الموت، لا متقدما\n⟦2:764⟧\nعليه ولا متأخرا عنه، وقولك: وأنت مسلم الأظهر منه أن\nيكون ذلك حاصلا من قبل، ومستصحبا في تلك الحال."}, {"a": [103], "v": 2, "p": 764, "ev": 2, "ep": 770, "sid": 965, "t": "قوله تعالى: (واعتصموا بحبل الله جميعا ولا تفرقوا واذكروا نعمت الله عليكم إذ كنتم أعداء فألف بين قلوبكم فأصبحتم بنعمته إخوانا وكنتم على شفا حفرة من النار فأنقذكم منها كذلك يبين الله لكم آياته لعلكم تهتدون (103).\nحبل الله: هو الذريعة المتوصل بها إليه من القرآن والنبي\nوالعقل والعلم، والاعتصام ضربان: اعتصام بالله بلا واسطة\nبشرية، وذلك للأنبياء، واعتصام بواسطة بشرية، وهو بمنزلة\nغيرهم من الناس، ثم منهم من يتوصل إليه بواسطة واحدة من\n⟦2:765⟧\nالوسائط، كالصحابة والأولياء والحكماء، الذين لم يأخذوا\nالدين بالتقليد، ومنهم من يحتاج مع ذلك إلى من يعتمده في\nكثير من دينه، وإلى هذا أشار النبي - صلى الله عليه وسلم - بقوله: \"أصحابي كالنجوم بأيهم اقتديتم اهتديتم \".\nإن قيل: لم قال أولا: ﴿وَمَن يَعۡتَصِم بِٱللَّهِ﴾⟪3:101⟫، ثم قال: ﴿وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ﴾⟪3:103⟫\nوجعل بين الكلمتين و (اتقوا الله)؟\nقيل: لما كان القصد في\n⟦2:766⟧\nعبادة الله إلى الاعتصام به ولا سبيل إلى ذلك إلا بالتقوى عقبه\nبقوله: و (اتقوا الله)، ولما كان حقيقة التقوى فعل الطاعات.\nولا سبيل للإنسان إلى معرفة ذلك إلا بحبل الله: أي كتابه ورسله\nأمر أن يعتصموا بحبله ليتوصلوا إلى تقواه، ومن تقواه إلى\nالاعتصام به، ومن توصل إلى الاعتصام، ثم إلى التوكل، ثم إلى\nالإسلام استغنى حينئذ عن الوسائط، الذين هم حبل الله، ويصير\n⟦2:767⟧\nممن قال - صلى الله عليه وسلم - فيه حكاية عن الله: \"فإذا أحببته كنت سمعه \"، الخبر.\n⟦2:768⟧\nوقوله: ﴿وَلَا تَفَرَّقُواْۚ﴾⟪3:103⟫ حث على الألفة والاجتماع، الذي هو\nنظام الايمان واستقامة أمور العالم، وقد فضل المحبة والألفة على\nالإنصاف والعدالة، لأنه يحتاج إلى الإنصاف حيث تفقد المحبة.\nولصدق محبة الأب للابن صار مؤتمنا على ماله، والألفة أحد ما شرف الله\nبه الشريعة سيما شريعة الإسلام، ولهذا قال: ﴿لَوۡ أَنفَقۡتَ مَا فِي ٱلۡأَرۡضِ جَمِيعٗا مَّآ أَلَّفۡتَ بَيۡنَ قُلُوبِهِمۡ وَلَٰكِنَّ ٱللَّهَ أَلَّفَ بَيۡنَهُمۡۚ﴾⟪8:63⟫.\nوقال : ﴿مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ﴾⟪48:29⟫، وقال - صلى الله عليه وسلم -: \"لا تقاطعوا ولا تدابروا، وكونوا عباد الله إخوانا\"،\n⟦2:769⟧\nوقال: \"من شذ شذ في النار\".\nولطلب الألفة شرع الاجتماعات في المساجد والجمع والجماعات والأعياد.\nوقوله: ﴿وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ﴾⟪3:103⟫ أي على ما يؤديكم إلى\nالنار، وهو خطاب عام للمسلمين كافة، وإن كان قد جعله\nبعضهم خاصا للأوس والخزرج على ما تقدم ذكره، وبعضهم\n⟦2:770⟧\nجعله للعرب، وأنهم كانوا في شدة وعري وجوع وتقاتل\nبينهم، فأزال الله تعالى عنهم ذلك بالإسلام، وقد تقدم الكلام\nفي قوله: ﴿كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ﴾⟪3:103⟫."}, {"a": [104], "v": 2, "p": 770, "ev": 2, "ep": 777, "sid": 971, "t": "قوله تعالى: (ولتكن منكم أمة يدعون إلى الخير ويأمرون بالمعروف وينهون عن المنكر وأولئك هم المفلحون (104)\nالمعروف: ما يستحسنه العقل ويرد به الشرع.\nوالمنكر: ما يستقبحه العقل\n⟦2:771⟧\nويحظره الشرع، وعلى ذلك يقال للسخاء المعروف في نحو\nقول الشاعر:\nولم أر كالمعروف أما مذاقه. . . فحلو وأما وجهه فجميل\nويقال لهما: الحق والباطل، والحسنى والسوءى، والصلاح\nوالفساد، والجميل والقبيح، وإنما اختلفت العبارات في ذلك\nبحسب اختلاف العبارات.\nواختلف في الأمر بالمعروف والنهي عن المنكر، هل ذلك واجب على كل إنسان أو على بعضهم دون بعض، فمنهم من جعله واجبا على العموم، وقال: إن من في\n⟦2:772⟧\nقوله (منكم) للتبيين، كما في قوله: ﴿فَٱجۡتَنِبُواْ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَٰنِ﴾⟪22:30⟫\nوقال: لأن حق الناس كلهم أن يكونوا خلفاء الله\nفي أرضه، وسواسا لبعض خلائقه، لكن السياسات ثلاث:\nسياسة الإنسان نفسه، وسياسته أهله وما يخصه، وسياسته بلده\nوصقعه، فسياسة البلد والصقع من وجه إلى الأئمة، وهو أخذهم\nالناس بالقهر، ومن وجه إلى الحكماء والعلماء. - فقهائهم ووعظتهم -\nوهو أخذهم بالوعظ، وكل ذلك فرض على الكفاية.\nوأما سياسة الإنسان نفسه فواجب على كل مكلف على التضييق.\nوكذا سياسة الأهل واجبة على من يملكه، ومنهم من جعل ذلك فرضا على\n⟦2:773⟧\nالكفاية، واستدل عليه من الآية بقوله: ﴿وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ﴾⟪3:104⟫، وذلك يقتضي التبعيض، واعتبر ذلك في سياسة\n⟦2:774⟧\nالإنسان لغيره دون سياسته نفسه ، وأجرى ذلك مجرى الجهاد\nوطلب العلم، وهذا أقرب على اعتبار الفقهاء، والأول أعم على\nاعتبار الحكماء، والذي تستحق به العقوبة هو ترك ما يلزم من\nحق غيرهم، وإياه قصد بقوله تعالى: ﴿لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ﴾⟪5:78⟫ إلى قوله ﴿كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ﴾⟪5:79⟫، وخص تركهم النهي عن المنكر دون الأمر بالمعروف، فإنه أعظم الأمرين إثما، وأوكدهما وجوبا، ففعل المعروف ليس بواجب على كل أحد، وترك المنكر واجب على كل حال.\nثم إنكار المنكر ثلاثة أضرب:\nإنكار باليد، وإنكار باللسان، وإنكار بالقلب.\nعلى حسب ما روي عن النبي - صلى الله عليه وسلم -:\n\"من رأى منكم منكرا فاستطاع أن يغيره فليغيره بيده، فإن لم يستطع\nفبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان \"،\n⟦2:775⟧\nفقيل: إن الأول للسلاطين، والثاني للعلماء، والثالث للعوام.\nفإن قيل: كيف حث هاهنا على الأمر بالمعروف،\n⟦2:776⟧\nوقال في غيره: ﴿عَلَيۡكُمۡ أَنفُسَكُمۡۖ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا ٱهۡتَدَيۡتُمۡۚ﴾⟪5:105⟫؟\nقيل في قوله: ﴿عَلَيۡكُمۡ أَنفُسَكُمۡۖ﴾⟪5:105⟫ قولان: أحدهما:\nإن ذلك حث على أن يغير الإنسان على نفسه قبل أن ينكره على\nغيره، وهو خطاب للعامة.\nوالثاني: ما قال أبو ثعلبة الخشني، وقد سئل عن هذه الآية فقال:\nسألت عنها خبيرا، لقد سألت رسول الله - صلى الله عليه وسلم - فقال: \" ائتمروا بالمعروف، وتناهوا عن المنكر،\n⟦2:777⟧\nفإذا رأيت شحا مطاعا، وهوى متبعا، وإعجاب كل ذي رأي\nبرأيه، فعليك نفسك، ودع عنك العوام \".\nوجعل تعالى الآمرين بالمعروف والناهين عن المنكر هم المفلحون، لأن\nمن تولى إصلاح نفسه، ثم صلاح غيره بغاية وسعه، فقد زكى\nنفسه، وزكى غيره، وقد قال تعالى فيمن يهذب نفسه: ﴿قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا﴾⟪91:9⟫، وقد تقدم أن الفلاح الحقيقي هو البقاء الأبدي والنعيم السرمدي."}, {"a": [105], "v": 2, "p": 778, "ev": 2, "ep": 781, "sid": 979, "t": "قوله تعالى: (ولا تكونوا كالذين تفرقوا واختلفوا من بعد ما جاءهم البينات وأولئك لهم عذاب عظيم (105)\nالتفرق على ثلاثة أضرب:\nتفرق بالأبدان، وتفرق بالأقو ال والأفعال، وتفرق بالاعتقادات.\nوكذلك الاختلاف؛ إلا أن الأظهر في الاختلاف أن\nيكون بالأقوال والأفعال والاعتقادات، وفي التفرق أن يكون\nبالأبدان، وذكر تعالى اللفظين، ليبين أن أهل الكتاب تجادلوا\nبكل ذلك، وعلى هذا قال ابن عباس والربيع: تفرقوا واختلفوا\nفي أحكام مبتدعة وأهواء متبعة بعد أن كانوا إخوانا، وإن من\nكان قبلهم هلكوا بالمراء والخصومات، ثم ذكر ما لهم من عظيم\n⟦2:779⟧\nالعذاب في الآخرة بالنار الدائمة، وفي الدنيا بمحنها ونوبها.\nونبه بقوله: ﴿وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ عَظِيمٞ﴾⟪3:105⟫ أن سبب استحقاقهم\nالعذاب افتراقهم واختلافهم، تنبيها أنكم إن فعلتم فعلهم\nاستحققتم العذاب استحقاقهم.\nإن قيل: كيف قال النبي - صلى الله عليه وسلم -:\n\"الاختلاف في أمتي رحمة\" مع ما ذكر من ذم الاختلاف؟\n⟦2:780⟧\nقيل: الاختلاف ضربان: اختلاف في الأصول الجارية من الطرق\nمجرى طريق الشرق من طريق الغرب، وذلك هو المذموم، فإن\nما عدا الجهة المأمور بسلوكها مؤد إلى الباطل. وإلى هذا يوجه\nقوله: ﴿وَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ﴾⟪6:153⟫.\nوالثاني: اختلاف في الفروع الجارية من الطرق مجرى بنيات طريق إلى مقصد واحد يسلكها، كل على حسب اجتهاده، ومقصد جميعهم واحد، فإن إباحة الله سلوك كل واحد من تلك الطرق فسحة لهم ورحمة، وإياه قصد بقوله:\n⟦2:781⟧\n﴿وَمَا جَعَلَ عَلَيۡكُمۡ فِي ٱلدِّينِ مِنۡ حَرَجٖۚ﴾⟪22:78⟫."}, {"a": [106, 107], "v": 2, "p": 781, "ev": 2, "ep": 788, "sid": 982, "t": "قوله تعالى: (يوم تبيض وجوه وتسود وجوه فأما الذين اسودت وجوههم أكفرتم بعد إيمانكم فذوقوا العذاب بما كنتم تكفرون (106)\nابيضاض الوجه عبارة عن المسرة، واسودادها عن الغم.\nوعلى ذلك ﴿ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا﴾، ثم قال: ﴿مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ﴾⟪16:59⟫.\n⟦2:782⟧\nوعلى ذلك قوله: ﴿وَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ﴾⟪80:40⟫.\nوهذا الابيضاض والاسوداد أبلغ من المحسوسين.\nوقال بعض المتكلمين: يحمل ذلك على المحسوس.\nلكونه حقيقة فيه، وهذا خطأ، وذلك لأنه لم يعلم\nأن ذلك حقيقة فيهما جميعا، فليس الاسوداد والابيضاض\nأكثر من كيفية عارضة في الوجه، قل ذلك أم كثر،\n⟦2:783⟧\nومعلوم أن من ناله غم شديد يعرض لوجهه - لتبرمه وتكدره -\nاسوداد في وجهه، وليس قلة السواد والبياض مما يخرج اللفظ\nعن الحقيقة، ثم حمل الآية على هذا أولى، لأن ذلك حاصل لأهل\nالقيامة باتفاق، سواء كانوا في الدنيا سودانا أو بيضانا، وعلى\nذلك ﴿وُجُوهٞ يَوۡمَئِذٖ نَّاضِرَةٌ﴾⟪75:22⟫ وقوله: (وجوه يومئذ مسفرة (38) ضاحكة مستبشرة).\nوأما كفرهم بعد إيمانهم فقد قال الحسن: بعد إظهارهم الإيمان بالنفاق)، وقال قتادة: كفروا بالارتداد بعد\n⟦2:784⟧\nالإسلام، وقيل: بعد الإقرار الذي اقتضاه قوله تعالى: ﴿أَلَسۡتُ بِرَبِّكُمۡۖ قَالُواْ بَلَىٰ﴾⟪7:172⟫.\nوقيل: كفروا بالنبي - صلى الله عليه وسلم - بعد أن أقروا به قبل\nبعثته، وعموم اللفظ يقتضي كل ذلك، ولا تنافي بينها.\nوقوله: (أكفرتم) تقديره: فيقال لهم: أكفرتم؟، وحذف القول\nمن نحو ذلك كثير نحو: ﴿وَلَوۡ تَرَىٰٓ إِذِ ٱلظَّٰلِمُونَ فِي غَمَرَٰتِ ٱلۡمَوۡتِ وَٱلۡمَلَٰٓئِكَةُ بَاسِطُوٓاْ أَيۡدِيهِمۡ أَخۡرِجُوٓاْ أَنفُسَكُمُۖ﴾⟪6:93⟫.\nوقوله: ﴿وَلَوۡ تَرَىٰٓ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُواْ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَآ أَبۡصَرۡنَا وَسَمِعۡنَا﴾⟪32:12⟫\n⟦2:785⟧\nأي يقولون، ولما حذف الفعل حذف معه الفاء\nالذي يكون جواب أما، ويوم ظرف لقوله عظيم، ولا يكون\nعند البصريين ظرفا لقوله عذاب، لأن الاسم إذا وصف لا يعمل\nعندهم.\nإن قيل: لم كرر لفظة ﴿فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪3:107⟫؟\nقيل: قال بعض النحويين: إن ذلك للتأكيد.\nوتمكين المعنى في النفس، وقيل: (قوله: ﴿فَفِي رَحۡمَةِ ٱللَّهِۖ﴾⟪3:107⟫ تمام\nالكلام، و ﴿هُمۡ فِيهَا خَٰلِدُونَ﴾⟪3:107⟫ تنبيها أن ذلك لهم مؤبدا،\n⟦2:786⟧\nوقيل: قوله: ﴿هُمۡ فِيهَا﴾⟪3:107⟫ راجع إلى مقتضى قوله: ﴿ٱبۡيَضَّتۡ وُجُوهُهُمۡ﴾⟪3:107⟫ وهو المسرة، تنبيها أن تلك المسرة دائمة لا كمسرات الدنيا التي تنقطع.\nوإن بقيت أسبابها. فأحوال الدنيا وإن كانت سارة متبرم منها بدوامها.\nولهذا قيل: للعافية تمل أكثر مما يمل البلاء.\nإن قيل: المقابلة في الاثنين غير صحيحة، فإن التقابل الصحيح أن يكون المذكور في الثانية عكس المذكور في الأولى، وليس قوله: ﴿فَفِي رَحۡمَةِ ٱللَّهِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪3:107⟫ عكسا لقوله: ﴿أَكَفَرۡتُم بَعۡدَ إِيمَٰنِكُمۡ﴾⟪3:106⟫؟\nقيل: مراعاة التقابل على ضربين: تقابل اللفظ، وتقابل المعنى.\nوهو أفضلهما عند أصحاب المعاني.\nفالتقابل حاصل من حيث المعنى، وعدل عن لفظ الخبر في قوله:\n(أكفرتم) وقوله: ﴿فَذُوقُواْ ٱلۡعَذَابَ﴾⟪3:106⟫ إشارة إلى ما يقال لهم،\n⟦2:787⟧\nونبه أنهم يقابلون مع العقوبة بالتبكيت، وقد قيل: التبكيت\nأعظم العقوبتين، وأن يقال لهم: (ذوقوا)، وذلك دلالة على مبالغة\nالغضب عليهم.\nإن قيل: كان الوجه أن يقال: ألستم قد كفرتم؟\nفلفظ الاستفهام في القرآن محمول على الإنكار، والإنكار متى تجرد\nعن حرف النفي يكون للنفي نحو قوله: ﴿ءَأَنتَ قُلۡتَ لِلنَّاسِ﴾⟪5:116⟫ وإذا\nكان للإثبات قرن به حرف النفي؟\nقيل: الألف في الأصل للاستخبار، والاستخبار أعم من الاستفهام.\nوكل استفهام استخبار، وليس كل استخبار استفهاما.\nوالمستخبر قد يقصد إلى أخذ إقرار المستخبر أو إلى إلجائه إلى الإقرار بما ينكره، وقوله: (أكفرتم) استخبار على هذا الوجه، وتقريع لهم، وعلى ذلك\n⟦2:788⟧\nقوله تعالى: ﴿أَتَأۡتُونَ ٱلذُّكۡرَانَ مِنَ ٱلۡعَٰلَمِينَ﴾⟪26:165⟫."}, {"a": [108], "v": 2, "p": 788, "ev": 2, "ep": 789, "sid": 989, "t": "قوله تعالى: (تلك آيات الله نتلوها عليك بالحق وما الله يريد ظلما للعالمين (108)\nقال الفراء: معناه هذه آيات الله، وقد تقدم الكلام في\nقوله: ﴿ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ﴾⟪2:2⟫، وآيات الله يصح أن تكون\nالكتاب، وأن تكون جميع الآيات المسموعة والمعقولة مما يظهره الله.\nويكون معنى (نتلوها) نبينها بوجوه التبينات،\n⟦2:789⟧\nقوله: (بالحق) أي الحق يقارنه، أو هو الحق، وفي قوله: ﴿وَمَا ٱللَّهُ يُرِيدُ ظُلۡمٗا﴾⟪3:108⟫ تنبيه على اعتبار ما تقدم ذكره لما اقتضى عدله في معاقبة الكفار."}, {"a": [109], "v": 2, "p": 789, "ev": 2, "ep": 790, "sid": 990, "t": "قوله تعالى: (ولله ما في السماوات وما في الأرض وإلى الله ترجع الأمور (109)\nقد تقدم تفسير ذلك، ونبه بقوله: ﴿وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾⟪3:109⟫ على شيئين: أحدهما: إبطال قول من زعم أن الأشياء تبقى عناصرها فلا تفنى.\nوالثاني: على أنه يصح أن يتوهم ارتفاع الأمور كلها مع بقائه تعالى.\nوأنه لا ينكر عدمها انتهاء، كما لا ينكر ذلك ابتداء.\nإن قيل: وما وجه إيراد هذا القول\n⟦2:790⟧\nفي هذا الموضع؟\nقيل: إنه لما بين تعالى ما اقتضى عدالته وعقبه\nبذكر التبرؤ من ظلمهم بين بهذا القول استغناءه عن الظلم، وأن\nالظلم يتحراه من يروم ما لغيره، ومحال أن يعتقد في مالك الكل\nومن منه البدء وإليه العود الظلم."}, {"a": [110], "v": 2, "p": 790, "ev": 2, "ep": 796, "sid": 991, "t": "قوله تعالى: (كنتم خير أمة أخرجت للناس تأمرون بالمعروف وتنهون عن المنكر وتؤمنون بالله ولو آمن أهل الكتاب لكان خيرا لهم منهم المؤمنون وأكثرهم الفاسقون (110)\nإن قيل: لم قال: (كنتم) ولم يقل: أنتم؟\nقيل: في ذلك أجوبة: الأول:\nكنتم فيما قضيت وقدرت وبنيت عليه الشرائع خير أمة بشريطة\nأن تأمروا بالمعروف، وتنهوا عن المنكر، وتؤمنوا بالله)،\n⟦2:791⟧\nفقد تقدم إن هذه الشريعة أكمل الشرائع، ولهذا قال - صلى الله عليه وسلم -:\n\"أنتم تتمون سبعين أمة، أنتم خيرها وأكرمها على الله تعالى\".\nوالثاني: أن الإشارة بذلك إلى من آمن بالنبي - صلى الله عليه وسلم - في ابتداء الإسلام، وإلى هذا ذهب عمر، وقال: هذا لأولنا، ولو شاء الله لجعله لآخرنا أيضا.\nفقال: أنتم، فكنا كلنا أخيارا.\nويؤكد ذلك ما روي\n⟦2:792⟧\nعن عبد الله قال: جمعنا رسول الله، ونحن أربعون رجلا، فقال:\n\"إنكم منصورون ومفتوح لكم، فمن أدرك ذلك منكم فليأمر\nبالمعروف ولينه عن المنكر\".\nالثالث: أن ما تشارك فيه الأحوال الثلاث: الماضي والحال والمستقبل.\nلا فرق بين أن تقول: كنت كذا أو أنت كذا، لأن القصد ليس إلى تخصيص الزمان، بل إلى ذكر ثبوت ذلك الشيء، وأيا من ذلك ذكرت، فإنه لا يقتضي من حيث اللفظ نفي الآخر، وإذا كان كذلك كان أولى الألفاظ بمثله: كان، لأنه يقتضي الحصول، ولا يقتضي تغيير ذلك الشيء من حيث\nاللفظ، وإذا أورد تعالى جل أوصافه على ذلك، نحو ﴿وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا﴾، وقيل: (كنتم) في اللوح\n⟦2:793⟧\nالمحفوظ، وهذا كالأول.\nإن قيل: لأي شيء وصفهم بأنهم خير أمة.\nوقد علم أن أشرار الناس في هذه الأمة أكثر من\nالأخيار، وأن كثيرا من الأمم المتقدمة كانوا حيرا من كثير هذه الأمة؟\nقيل: ليس الاعتبار بأشخاص الناس، وإنما الاعتبار بما\nصارت الأمة به أمة، والشريعة به شريعة، وقد تقدم أن هذه\nالشريعة أفضل الشرائع إذا اعتبرت بها، على أنه قد قيد\nفقال: ﴿تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ﴾⟪3:110⟫، أي أنتم خير أمة على هذه\nالشريطة لأن قوله: (تأمرون) في موضع الحال.\n⟦2:794⟧\nقال ابن عباس ومجاهد وأبو هريرة: كونهم خيرا هو أنه لم\nيؤمر نبي قبله بالقتال، وقهر الناس على الدخول فيما فيه\nصلاحهم إلا هذه الأمة، فإن الله يقودهم بالسلاسل من\nالكفر إلى الإيمان، وقال غيرهم: لم يكن في أمة من الآمرين\n⟦2:795⟧\nبالمعروف، والناهين عن المنكر أكثر مما في هذه الأمة.\nإن قيل: لم أخر الإيمان بالله عن الأمر بالمعروف والنهي عن المنكر؟\n⟦2:796⟧\nقيل: الإيمان هاهنا ليس هو الإقرار بالله فقط، بل هو الوفاء\nبشروطه والقيام بشرائعه، الذي هو تمام الإيمان وكماله\nعلى ما ذكرناه فيما تقدم، وقال: ﴿وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ﴾⟪3:110⟫\nفقابل به المؤمنين، لأن الفسق أعم من الكفر، فبين أن\nالمؤمنين المخلصين قليل جدا، وأن أكثرهم فاسق: إما كافر.\nوإما منافق."}, {"a": [111], "v": 2, "p": 796, "ev": 2, "ep": 798, "sid": 997, "t": "قوله تعالى: (لن يضروكم إلا أذى وإن يقاتلوكم يولوكم الأدبار ثم لا ينصرون (111)\nقال ابن عباس والحسن: عنى بالأذى الكلام المؤذي.\nوجعل بعضهم الآية مخصوصة\n⟦2:797⟧\nفي بني قريظة، قال: ووحد المخبر على ما أخبر به تعالى، وجعلها\nبعضهم عامة، وقال: إن كان ما ينال المؤمنين من الكفار كلاما\nكان أو قتالا فهو أذى عارض (والعاقبة للمتقين)، كما\nقال في غير موضع.\nوقوله: ﴿ثُمَّ لَا يُنصَرُونَ﴾⟪3:111⟫ لم يجزمه، لأنه إذا جعل جوابا اقتضى أن النصرة عنهم ممنوعة في حال المقابلة فقط،\n⟦2:798⟧\nوإذا رفع اقتضى أنهم ممنوعون عنها في كل حال.\nوقال بعض النحويين: رفع ذلك ليكون كماخر سائر الآيات المتقدمة.\nوهذا القول هو بحسب مراعاة اللفظ دون المعنى."}, {"a": [112], "v": 2, "p": 798, "ev": 2, "ep": 803, "sid": 999, "t": "قوله تعالى: (ضربت عليهم الذلة أين ما ثقفوا إلا بحبل من الله وحبل من الناس وباءوا بغضب من الله وضربت عليهم المسكنة ذلك بأنهم كانوا يكفرون بآيات الله ويقتلون الأنبياء بغير حق ذلك بما عصوا وكانوا يعتدون (112)\nقيل: هي مخصوصة في بني قريظة على ما تقدم.\nوقيل: هو أمر وإن كان لفظه خبرا، فأمر بتذليل أهل\nالكتاب، وأخذ الجزية منهم على ما ذكره الفقهاء وبينوه.\nوقيل: هو خبر عام عن جميعهم.\nفإن قيل: كيف يصح ذلك\n⟦2:799⟧\nمع أنه قد يرى من أهل الكتاب من لا يكون في مذلة ولا فقر.\nقيل: المذلة هي التي تلزمهم ليس يجب أن تعتبر في الأشخاص.\nولا في الأعراض الدنيوية من الجاه والمال، بل يجب أن يعتبر ذلك\nبالأحوال الشرعية، والعز والذل الحقيقيين، اللذين يقتضيهما الدين.\nوإياه قصد بقوله: ﴿وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِينَ وَلَٰكِنَّ ٱلۡمُنَٰفِقِينَ لَا يَعۡلَمُونَ﴾⟪63:8⟫ وقد قيل: كل عز مصيره إلى ذل فهو ذل، وما يتصوره بعض الناس عزا من غرور الدنيا فهو المذلة عند التحقيق.\nوكذلك المسكنة ليست قلة المال، وإنما هي الحرص، وفقر النفس.\nولهذا روي عن النبي - صلى الله عليه وسلم - أنه قال:\n\"الغنى غنى النفس \"\n⟦2:800⟧\nوقيل لحكيم: هل لفلان غنى؟\nفقال: أما الغنى فلا أدري، إلا أن له مالا كثيرا.\nوقال الشاعر:\n. . . قد يكثر المال والإنسان مفتقر.\nوقيل: إن ذلك على سبيل الدعاء عليهم، كقوله تعالى:\n﴿قَٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ يُؤۡفَكُونَ﴾، وقوله: ﴿قُتِلَ ٱلۡخَرَّٰصُونَ﴾⟪51:10⟫، وهذا في الحقيقة يرجع إلى الأول، فالدعاء من الله واجب.\nإن قيل: لم قال: ﴿إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ وَحَبۡلٖ مِّنَ ٱلنَّاسِ﴾⟪3:112⟫\nفأعاد ذكر الحبل، وفصل؟\nقيل: لأن الكافر يحتاج إلى حبلين أي عهدين، عهد من الله.\nوهو أن يكون من أهل كتاب أنزله الله، وإلا لم يكن مقرا على دينه بالذمة، ثم يحتاج إلى حبل من الناس،\n⟦2:801⟧\nأي أمان وعهد يبذلونه على ما بينه الفقهاء.\nوالناس هاهنا خاص للمسلمين، وقوله: ﴿وَبَآءُو بِغَضَبٖ مِّنَ ٱللَّهِ﴾⟪3:112⟫\nأي استحقوا عقابا منه، وقوله: ﴿ذَٰلِكَ بِأَنَّهُمۡ﴾⟪3:112⟫ أي نالهم ذلك بكفرهم.\nوقوله من بعد: ﴿ذَٰلِكَ بِمَا عَصَواْ﴾⟪3:112⟫ قيل: هو بدل من الأول.\nفإن كفرهم ليس هو إلا عصيانهم، واعتداؤهم.\nوقيل: بل جعل الكفر علة لما نالهم من الذلة والمسكنة.\nوجعل عصيانهم علة لكفرهم، وذلك أن الذنوب الصغائر\nإذا استمر عليها الإنسان أفضت إلى الكبائر.\nوالكبائر تفضي إلى الكفر، ولهذا قال\n⟦2:802⟧\nتعالى: ﴿ثُمَّ كَانَ عَٰقِبَةَ ٱلَّذِينَ أَسَٰٓـُٔواْ ٱلسُّوٓأَىٰٓ أَن كَذَّبُواْ بِـَٔايَٰتِ ٱللَّهِ﴾⟪30:10⟫.\nوقال - صلى الله عليه وسلم -: \"الذنب على الذنب حتى يسود القلب \".\nوفي قوله: ﴿ذَٰلِكَ بِمَا عَصَواْ﴾⟪3:112⟫ تحذير لنا وتنبيه، كأنه قال: اجتنبوا\nالمعصية، وهي التي أدت بهم إلى الكفر المقتضي لعظم العقوبة\nإن قيل: كيف قال: ﴿إِلَّا بِحَبۡلٖ مِّنَ ٱللَّهِ﴾⟪3:112⟫، ولا يصح في الإثبات\nأن يقال: اعتصمت إلا بحبل فلان، والاستثناء في الإثبات لا يكون\nإلا من لفظ عام؟\nقيل: إن قوله: ﴿أَيۡنَ مَا ثُقِفُوٓاْ﴾⟪3:112⟫ مقتض لمعنى\n⟦2:803⟧\nالعموم، كأنه قيل: بكل حال، فيصح أن يقال: إلا بحبل."}, {"a": [113], "v": 2, "p": 803, "ev": 2, "ep": 807, "sid": 1004, "t": "قوله تعالى: (ليسوا سواء من أهل الكتاب أمة قائمة يتلون آيات الله آناء الليل وهم يسجدون (113)\nالأمة: الجماعة، وقد تقدم.\nوجعلها الزجاج هاهنا الاستقامة.\nوقال: تقديره: ذوو طريقة مستقيمة، والأول أولى.\nلأنه لا يحتاج فيها إلى إضمار.\nوالقائمة: العادلة،\n⟦2:804⟧\nوقال مقاتل: مطيعة، وقال بعضهم: مسلمة، وهذا\nكلة واحد، فإن العادل لا يكون عادلا حتى يكون مسلما مطيعا.\nوالمطيع لا يكون مطيعا حتى يكون مسلما عادلا.\nوالآناء: جمع إني كانحاء في جمع نحي، وقيل: هو جمع إنى نحو معا وأمعاء.\nوقوله: ﴿لَيۡسُواْ سَوَآءٗۗ﴾⟪3:113⟫ كلام تام أي لا يستوون.\nثم قال: ﴿أُمَّةٞ قَآئِمَةٞ﴾⟪3:113⟫ أي منهم أمة قائمة.\nوقال بعضهم: تقديره:\n⟦2:805⟧\nأي ليسوا سواء هم وأمة قائمة، يعني أمة محمد - صلى الله عليه وسلم -، وإليه ذهب ابن مسعود، وقال: لا يستوي أهل الكتاب، وأمة محمد.\nوقال الفراء: ذكر أمة قائمة، وحذف الأخرى كقول الشاعر:\n. . . . . . . . . . . . . . . . . . . . . . . . . فما أدري أرشد طلابها\nوتقديره: أم غي، وما قاله إنما يصح إذا جعل (أمة) بدلا\n⟦2:806⟧\nمن الضمير في (ليسوا)، أو جعل الواو فيه كالواو في أكلوني\nالبراغيث، ويجعل (أمة) اسم ليس، وتكون المفاضلة\nبين أمة قائمة وأمة غير قائمة.\nوقوله: ﴿يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ﴾⟪3:113⟫\nقيل: عنى به صلاة العتمة، لأنها لم تكن إلا لهذه الأمة.\nواستدل بما روي أن النبي - صلى الله عليه وسلم - أخر صلاة العشاء\nليلة، ثم خرج إلى المسجد، فإذا الناس ينتظرونه.\nفقال: \"إنه ليس أحد من أهل الأديان يذكر الله في هذه الساعة غيركم \".\nفأنزل الله تعالى هذه الآية، وقيل: عنى الصلاة بين\n⟦2:807⟧\nالعشائين، وقيل: تلاوة القرآن بينهما، والسجود.\nقيل: عبارة عن الصلاة.\nوقوله: ﴿يَتۡلُونَ ءَايَٰتِ ٱللَّهِ ءَانَآءَ ٱلَّيۡلِ وَهُمۡ يَسۡجُدُونَ﴾⟪3:113⟫\nكلاهما في موضع الصفة ل (أمة قائمة)."}, {"a": [114], "v": 2, "p": 807, "ev": 2, "ep": 810, "sid": 1008, "t": "قوله تعالى: (يؤمنون بالله واليوم الآخر ويأمرون بالمعروف وينهون عن المنكر ويسارعون في الخيرات وأولئك من الصالحين (114)\n⟦2:808⟧\nذكر تعالى حال الأمة التي تقدم ذكرها، وابتدأ بذكر الإيمان بالله.\nوعنى الإيمان الذي لا تصح عبادة من دونه.\nوالمسارعة والمبادرة والعجلة تتقارب ، لكن السرعة أعمها\nوالمبادرة لا تكاد تستعمل إلا في البدن، والعجلة أكثر ما\nتستعمل فيما يتحرى عن غير فكر وروية، أو في إمضاء العزيمة\nقبل استكمال الروية، ولهذا يقال: \"العجلة من الشيطان \"،\n⟦2:809⟧\nوقال تعالى: ﴿وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ﴾⟪20:114⟫\nفإن قيل: لو كانت مذمومة لما قال موسى: ﴿وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ﴾⟪20:84⟫.\nقيل: موسى عليه السلام أورد ذلك على سبيل الاعتذار إبانة أنه قصد فعلا محمودا، وإن تحرى العجلة فيه، ومن قصد فعلا محمودا فقد يعذر في وقوع ما يكره منه، والمسارعة في الخير هي أن يتدرج الإنسان في ازدياد العرفة بفضله، واختياره والسرور بتعاطيه، وتقديمه على الأمور الدنيوية، وأن لا تؤخره عن أول وقت إمكان فعله وعلى ذلك قوله تعالى: ﴿سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ﴾⟪57:21⟫، ومدح تعالى قوما فقال: ﴿وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ﴾⟪56:10⟫.\nأي يسابقون بهممهم وأبدانهم، فلذلك كرره، ولمراعاة\nالمسارعة وكون بعض المسارعين أعلى منزلة من بعض،\n⟦2:810⟧\nقال تعالى: ﴿هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ﴾⟪3:163⟫، وبين تعالى في آخر الآية أن\nفاعل ذلك من الصالحين، والأقرب في من أن تكون للتبيين.\nوأنهم هم الصالحون، ولذلك قال في الأول ﴿وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾."}, {"a": [115], "v": 2, "p": 810, "ev": 2, "ep": 813, "sid": 1011, "t": "قوله تعالى: (وما يفعلوا من خير فلن يكفروه والله عليم بالمتقين (115)\nقرئ بالياء ردا إلى قوله: ﴿أُمَّةٞ قَآئِمَةٞ﴾⟪3:113⟫.\nوقرئ بالتاء لإدخال المخاطبين فيهم وتغليبا للخطاب،\n⟦2:811⟧\nوقوله: ﴿فَلَن يُكۡفَرُوهُۗ﴾⟪3:115⟫ كقوله: ﴿وَمَا تُنفِقُواْ مِنۡ خَيۡرٖ يُوَفَّ إِلَيۡكُمۡ﴾⟪2:272⟫\nوقوله: ﴿وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ﴾⟪2:197⟫، كل ذلك تنبيه على\nأن عمل المحسنين لا يضيع المدلول بقوله: ﴿إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ﴾⟪17:7⟫، وقوله: ﴿فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ﴾.\nوقوله: ﴿إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا﴾⟪18:30⟫.\nوأنهم بخلاف الكفار الذين قال فيهم: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ﴾⟪25:23⟫ الآية. وقوله: ﴿هَلۡ نُنَبِّئُكُم بِٱلۡأَخۡسَرِينَ أَعۡمَٰلًا﴾⟪18:103⟫ الآية.\nوقال الجبائي: (فلن يكفروه) مجاز في هذا الموضع، لأن\n⟦2:812⟧\nوصف الله بانه يشكر مجاز، وقوله ذلك لتصوره الشكر على\nوجه واحد، والشكر باعتبار الشاكر والمشكور على ثلاثة أوجه:\nشكر الإنسان لمن فوقه، وذلك بالخدمة والحمد، وشكره لنظيره .\nوذلك بالمقابلة، وشكره لمن دونه، وذلك بالإثابة، ولذلك يمدح\nتعالى بأنه شكور، وقال: ﴿وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ﴾⟪27:40⟫\nتنبيها أنه يقابله بالشكر الذي هو الثواب، ولعله تصور أن\nالشكر لا يكون إلا بالقول، ومن الأدون للأعلى، وذلك فاسد\n⟦2:813⟧\nلقوله تعالى: ﴿ٱعۡمَلُوٓاْ ءَالَ دَاوُۥدَ شُكۡرٗاۚ﴾⟪34:13⟫ فجعل الشكر\nمعمولا، ووصفه بأنه شكور وشاكر."}, {"a": [116], "v": 2, "p": 813, "ev": 2, "ep": 814, "sid": 1014, "t": "قوله تعالى: (إن الذين كفروا لن تغني عنهم أموالهم ولا أولادهم من الله شيئا وأولئك أصحاب النار هم فيها خالدون (116)\nأغناه: إذا جعل له غنى، وأغنى عنه: جعل له غناء في\nالدفع، ولما ذكر في الآية الأولى أن ما يفعله الإنسان من الخير لن\nيكفر، بين أن ما يعدونه خيرا إنما ينفع بعد الإيمان، فأما مع\n⟦2:814⟧\nافتقاده فلا نفع، وذكر أجل ما هو عندهم خير، وهو الأموال\nوالأولاد، وأنها لا تغني عنهم، وعلى ذلك ما حكى عن الكفار:\n﴿مَآ أَغۡنَىٰ عَنِّي مَالِيَهۡۜ﴾⟪69:28⟫ وجعلهم أصحاب النار لملازمتهم إياها."}, {"a": [117], "v": 2, "p": 814, "ev": 2, "ep": 819, "sid": 1015, "t": "قوله تعالى: (مثل ما ينفقون في هذه الحياة الدنيا كمثل ريح فيها صر أصابت حرث قوم ظلموا أنفسهم فأهلكته وما ظلمهم الله ولكن أنفسهم يظلمون (117).\nالصر: برد يحرق النبات.\nوقال مجاهد: هو النار.\n⟦2:815⟧\nوأصله صوت النار، وكأنه حكى به الصرير والصرصرة.\nونحوهما، والآية قيل: نزلت في أبي سفيان وأهل مكة\n⟦2:816⟧\nلإنفاقهم المال في معاداة النبي - صلى الله عليه وسلم -، لما بين في الآية الأولى أن مالهم لا يغني عنهم، بين أن إنفاق هؤلاء مع كونه غير نافع ضار\nلهم، وراجع بالوبال عليهم، فمن المفسرين من قال القصد\nإلى تشبيه ما لهم المنفق بالحرث. المحرق، وكفرهم المهلك بريح\nذات صر، لكن أخرج التشبيه ملفوفا لا مكشوفا، على تحقيق\nمطابقة لفظ المشبه والمشبه به، وذلك نحو ما تقدم.\nومنهم من قال: القصد في ذلك تشبيه أموالهم في إهلاكها إياهم بريح\nذات صر في كونها مهلكة لحرث قوم، ثم اختلفوا في هذه\nالنفقة، فمنهم من جعلها لما أنفقه هؤلاء وأمثالهم في معاداة\n⟦2:817⟧\nالمسلمين، كقوله: ﴿إِنَّ ٱلَّذِينَ كَفَرُواْ يُنفِقُونَ أَمۡوَٰلَهُمۡ لِيَصُدُّواْ عَن سَبِيلِ ٱللَّهِۚ فَسَيُنفِقُونَهَا ثُمَّ تَكُونُ عَلَيۡهِمۡ حَسۡرَةٗ ثُمَّ يُغۡلَبُونَۗ﴾⟪8:36⟫.\nومنهم من جعلها لكل ما ينفقه الكافر، أي شيء أنفقه فإن\nالكافر معاقب في ذلك كله، كما أن المؤمن مثاب على ما أنفقه على\nأي وجه أنفقه، وعلى هذا قال - صلى الله عليه وسلم - لسعد:. \"إنك لتؤجر في نفقتك كلها، حتى اللقمة تضعها في في امرأتك \".\nووجه ذلك أن المؤمن\n⟦2:818⟧\nلا يأخذ إلا من حيث على ما يجب وكما يجب، ولا يضع\nإلا كذلك، والكافر بخلاف ذلك، ومنهم من قال: ﴿مَا يُنفِقُونَ﴾⟪3:117⟫\nعبارة عن أعمالهم كلها، لكن خص الإنفاق لكونه أظهر\nوأكثر، وإنما خص حرث قوم ظلموا أنفسهم من أجل أن\nالناس فيما يصيبهم أمن، الجائحة ضربان:\nصالح لا يستحق عقوبة، فإذا نالته صار ذلك له أجرا مدخرا.\nفكأنه لم يضع ماله، وسيئ يستحق عقوبة، فإذا نالته فقد ضاع ماله في الحال وفي المآل، ومنهم من قال: معنى (ظلموا أنفسهم) أي زرعوا\nالحرث في غير وقته، تنبيها أن الكفار أساءوا فيما كان ينبغي\nلهم أن يفعلوه إساءة هؤلاء الحراث في حرثهم من تقديم أو تأخير.\nإن قيل: كيف قال: ﴿رِيحٖ فِيهَا صِرٌّ﴾⟪3:117⟫، وقد قيل: متى\nهبت الريح لم يؤثر الصر؟\nقيل في ذلك أجوبة:\n⟦2:819⟧\nالأول: أن كل صر لا ينفك من ريح معه، لكن التي معها الصر ضعيفة بحيث\nلا يحس بحركتها، وإنما تمنع الصر إذا تحركت حركة شديدة.\nوالثاني: أنه تعالى خص ذلك تنبيها أن أموالهم بطلت من حيث لم\nيحتسبوا: كبطلان حرث هؤلاء من حيث لم يحتسبوا، فإنهم كانوا\nآمنين من الصر لوجود الريح.\nوالثالث: أنه عنى بالصر صوت الريح وشدة عصوفها، وعنى أنها أصابته الريح ففرقته، كقوله: ﴿كَرَمَادٍ ٱشۡتَدَّتۡ بِهِ ٱلرِّيحُ فِي يَوۡمٍ عَاصِفٖۖ﴾⟪14:18⟫، ونحو هذه الآية في بطلان عمل الكفار قوله: ﴿وَٱلَّذِينَ كَفَرُوٓاْ أَعۡمَٰلُهُمۡ كَسَرَابِۭ بِقِيعَةٖ﴾⟪24:39⟫.\nوقوله: ﴿وَمَا ظَلَمَهُمُ ٱللَّهُ﴾⟪3:117⟫ فإنما عقب به لأنه لما كان أخذ مال الغير وإبطاله قد يتصوره من لا يعرف حقيقة الأمر بصورة الظلم بين أنه لم يظلمهم، بل هم ظلموا أنفسهم، حيث لم يضعوا مال الله حيث أمرهم."}, {"a": [118], "v": 2, "p": 819, "ev": 2, "ep": 824, "sid": 1020, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تتخذوا بطانة من دونكم لا يألونكم خبالا ودوا ما عنتم قد بدت البغضاء من أفواههم وما تخفي صدورهم أكبر قد بينا لكم الآيات إن كنتم تعقلون (118)\n⟦2:820⟧\nالبطانة في الثوب بإزاء الظهارة، ويستعمل لمن اختصصته كالشعار والدثار، ويقال: لبست فلانا إذا اختصصته، وعلى ذلك قوله: ﴿هُنَّ لِبَاسٞ لَّكُمۡ﴾⟪2:187⟫\nوألوت في الحاجة: قصرت، وألوت، فلانا ألوا أي أوليته\nتقصيرا بحسب الجهد، فقولك جهدا تمييز -\n⟦2:821⟧\n﴿وَلَا يَأۡتَلِ أُوْلُواْ ٱلۡفَضۡلِ﴾⟪24:22⟫ أي لا يقصروا، آلى أي حلف، هو أفعل من\nذلك، كأنه أزال التقصير ببذل ذلك القول.\nفقوله: ﴿لَا يَأۡلُونَكُمۡ خَبَالٗا﴾⟪3:118⟫ أي لا يقصرون في إيصال الخبال إليكم.\nوالخبال: الفساد، الذي يلحق ذات الحيوان.\nيقال: في قوائم الفرس خبل وخبال، أي فساد من جهة الاضطراب، وفلان مختبل الرأي، وقول زهير:\nهنالك إد يستخبلوا المال يخبلوا. . .\n⟦2:822⟧\nأي إن طلب المال منهم إفساد شيء من إبلهم فعلوا، والعنت\nتحري المشقة، يقال: عنت فلان عنتا، وأعنتة غيره، وعنته.\nقال تعالى: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ﴾⟪2:220⟫.\nوأكمة عنوت: صعبة المسلك، وعنود والمعاندة والمعانتة يتقاربان، لكن المعاندة هي الممانعة، والمعانتة: أن يتحرى مع الممانعة مشقة.\nقال ابن عباس: سبب نزول هذه الآية أن قوما صافوا جماعة من اليهود، فنهاهم الله تعالى عن ذلك، والآية تقتضي النهي عن الركون إلى من وما\n⟦2:823⟧\nيتحرى بك طريقة فساد: إنسانا كان أو شيطانا أو قوة من قوى\nنفسك تحيد بك عن الحق، كالهوى ونحوه، وقال - صلى الله عليه وسلم -: \"ما بعث الله من نبي ولا استخلف من خليفة إلا كانت له بطانتان.\nبطانة تأمره بالخير، وتحضه عليه، وبطانة تأمره بالشر وتحضه\nعليه \".\nونهى عمر عن الاستعانة بالكفار، واحتج بهذه الآية،\n⟦2:824⟧\nوقد تقدم الكلام في أنه على أي وجه لا يصح الاستعانة بهم.\nونبه بالاستدلال بكلامهم على فساد اعتقادهم، وأن ذلك لا يخفى\nمنهم، كقوله: ﴿وَلَتَعۡرِفَنَّهُمۡ فِي لَحۡنِ ٱلۡقَوۡلِۚ﴾⟪47:30⟫، وعلى نحوه قال\nالشاعر:\nولا حن بالبغضاء والنظر الشزر\nثم بين أن مالا يبدو منهم أكثر، وأخبر بقوله: ﴿قَدۡ بَيَّنَّا لَكُمُ﴾⟪3:118⟫\nأنه أظهر ما يمكنهم الاستدلال به على معاداتهم."}, {"a": [119], "v": 2, "p": 824, "ev": 2, "ep": 829, "sid": 1025, "t": "قوله تعالى: (ها أنتم أولاء تحبونهم ولا يحبونكم وتؤمنون بالكتاب كله وإذا لقوكم قالوا آمنا وإذا خلوا عضوا عليكم الأنامل من الغيظ قل موتوا بغيظكم إن الله عليم بذات الصدور (119).\n⟦2:825⟧\nالعض معروف، ومنه رجل عف: شديد الخصومة، كقولهم:.\nأزوم، وفلان يازم المأزم ونيب على كذا، والعض: علف الأمهار\nمما له مضغ شديد كالنوى والقت اليابس. والأنامل واحدتها\nأنملة، ولم يأت أفعل مفردا إلا قولهم: بلغ\n⟦2:826⟧\nأشده، وقد كثر ذلك في الجمع، نحو: أكلب وأفلس.\nويعبر عن التأسف بقرع السن وعض الأنامل، وذلك لا نشاهد من\nحال المتأسف، قال الشاعر:\nعضضت أناملي وقرعت سني\nأكلت يدي لما جنته تندما\n⟦2:827⟧\nوالغيظ هو الغضب والغم، فإن الغضب يقال فيما معه القدرة.\nعلى الانتقام، والغم فيما ليس معه قدرة الانتقام، والغيظ فيما\nليس معه تمام القدرة على الانتقام، ولذلك يستعمل في صفات\nالله الغضب دون الغيظ، والكتاب كله يعنى الكتب المنزلة.\nفوضع موضع الجمع، إما لكونه للجنس كقولك: كثر الدرهم\nفي أيدي الناس، أو لكونه في الأصل مصدرا.\nولفظ الإفراد أولى في هذا الموضع، لأنه يتضمن أنهم يؤمنون بما أنزل إليك وما أنزل من قبلك، ويتضمن أنهم يؤمنون بتفاصيل كل كتاب.\nبخلاف من قال فيهم: ﴿وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ﴾⟪4:150⟫.\nوقوله: (أولاء) قيل: معناه الذين، وتحبونهم صلته،\n⟦2:828⟧\nوقيل: معناه هؤلاء، وفيه وجهان: الأول: أن يكون كقولك\nها أنا ذا، وها أنتم هؤلاء، فيكون هؤلاء خبر الابتداء.\nو (تحبونهم) في موضع الحال، وهم راجع إلى ما تقدم ذكره.\nوالثاني: أن يكون هؤلاء مبتدأ ثانيا، و (تحبونهم) خبره.\nوالجملة خبر للأول، كقولك: أنت زيد تحبه، ويكون هم راجعا إلى\nهؤلاء. ومحبتهم لهم: إرادة الإسلام لهم، لأن ثمرة المحبة\nالنصيحة وإرادة الخير، وبين أنهم لا يحبون ذلك لكم، لأنهم لا\nيريدون لكم الإسلام الذي هو الخير المحض، ثم بين أنكم\nتؤمنون بكتب الله، وهم لا يؤمنون ببعض الكتاب.\nوقوله: ﴿وَإِذَا لَقُوكُمۡ﴾⟪3:119⟫ كقوله: ﴿وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ﴾،\n⟦2:829⟧\nوقوله: ﴿يَقُولُونَ بِأَفۡوَٰهِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ﴾⟪3:167⟫.\nوقوله: ﴿ءَامِنُواْ بِٱلَّذِيٓ أُنزِلَ عَلَى ٱلَّذِينَ ءَامَنُواْ وَجۡهَ ٱلنَّهَارِ وَٱكۡفُرُوٓاْ ءَاخِرَهُۥ﴾⟪3:72⟫\nوقوله: ﴿مُوتُواْ بِغَيۡظِكُمۡۗ﴾⟪3:119⟫ دعاء عليهم وإيجاب ذلك لهم، وإن لم يكن إيجابا\nعليهم، وقوله: ﴿عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ﴾⟪3:119⟫ كقوله ﴿يَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى﴾⟪20:7⟫.\nوقوله: ﴿يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ﴾⟪2:235⟫\nوقوله: ﴿يَعۡلَمُ خَآئِنَةَ ٱلۡأَعۡيُنِ وَمَا تُخۡفِي ٱلصُّدُورُ﴾⟪40:19⟫ ونحو ذلك."}, {"a": [120], "v": 2, "p": 829, "ev": 2, "ep": 834, "sid": 1030, "t": "قوله تعالى: (إن تمسسكم حسنة تسؤهم وإن تصبكم سيئة يفرحوا بها وإن تصبروا وتتقوا لا يضركم كيدهم شيئا إن الله بما يعملون محيط (120)\n⟦2:830⟧\nالحسنة: عبارة عن كل ما يستحسنه الإنسان مما يسره\nمن نعمة ينالها في بدنه وماله، وجاهه، والسيئة تضادها.\nوالمس والإصابة يستعملان في الخير والشر، إلا أن المصيبة\nاختصت، بما يسوء، ويقال: ضره يضره وضاره\n⟦2:831⟧\nيضيره، وقرئ: لا يضركم، والضمة فيه إتباع للضاد.\nنحو مد، ويجوز الفتح والكسر كما يجوز في مد.\nوقال بعض النحويين لا يضركم مرفوع رفعا صحيحا، وتقديره: فلا\nيضركم، وحذف الفاء كقول الشاعر:\n⟦2:832⟧\nمن يفعل الحسنات الله يشكرها. . . . . . . . . . . . . . . . . . . . . .\nوهذا إنما يجوز في ضرورة الشعر، والكيد: الاحتيال\nللغير بمكر ومقاساة، وعلى سبيل تصور هذا المعنى قيل: فلان\nيكيد بنفسه، والمكر مثله إلا أنه أعم، لأنه قد يقال في اجتلاب\nالمنفعة.\nإن قيل: على أي وجه يمنع صبرهم وتقواهم من أن\n⟦2:833⟧\nيضيرهم كيدهم، قيل: من أوجه: الأول: من الفيض الإلهي\nوالنصرة الموعود بها في نحو قوله: ﴿إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ﴾⟪39:10⟫ وقوله: ﴿مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ﴾⟪12:90⟫.\nوالثاني: أن من عرف منه الجد أحجم عنه العدو.\nكما قال رجل ضئيل أسر رجلا قويا، فسأله أمير المؤمنين:\nكيف تمكنت منه؟\nفقال: وقع في قلبي أني آخذه ولا أبالي بالقتل، ووقع\nفي قلبه أنه مأخوذ وخاف القتل، فنصرني عليه خوفه وجرأتي.\nوالثالث: أن المتذري بالصبر والتقوى تتحمل نفسه الشدائد.\nفلا يبالى بمكايدة عدوه.\nوالرابع: أن الثقة بنصر الله أعظم ناصر.\nوالإحاطة بالشيء يقال على وجهين:\nأحدهما: في الأجسام.\nوالثاني: في العلم بالشيء والقدرة عليه.\nفأما العلم فبأن يعلم حقيقة المحاط به ووجوده وجنسه وأوصافه، والغرض\n⟦2:834⟧\nالمقصود منه، وعلى ذلك: ﴿أَحَاطَ بِكُلِّ شَيۡءٍ عِلۡمَۢا﴾⟪65:12⟫ فصار\nقوله: ﴿بِمَا يَعۡمَلُونَ مُحِيطٞ﴾⟪3:120⟫ كقوله: ﴿لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ﴾⟪3:5⟫.\nوقو له: (سميع عليم) ونحوه."}, {"a": [121], "v": 2, "p": 834, "ev": 2, "ep": 836, "sid": 1035, "t": "قوله تعالى: (وإذ غدوت من أهلك تبوئ المؤمنين مقاعد للقتال والله سميع عليم (121)\nالتبوء: التمكن، يقال بوأته مكان كذا، أو لمكان كذا، وقيل: في حرف ابن مسعود:\n⟦2:835⟧\nتبوئ للمؤمنين، وإذ قيل معطوف على قوله: ﴿قَدۡ كَانَ لَكُمۡ ءَايَةٞ فِي فِئَتَيۡنِ﴾⟪3:13⟫ آية في غلبتكم - مع قلتكم - الكفار مع كثرتهم.\nوآية إذ غدوت ترتاد للمؤمنين مكانا للقتال، فانكشف الحال عما\nكان لهم فيه آية، ولما أمرهم بالصبر والتقوى ذكرهم ما خولهم\nببدر حيث صبروا واتقوا، وبأحد حيث كان منهم ما كان.\nوذاك أن النبي - صلى الله عليه وسلم - شاور أصحابه حيث قصده المشركون: هل يخرج إليهم أو يقيم بالمدينة فيقاتلهم فيها، وذلك هو معنى تبوئه للقتال أي موضع المشاورة، ولهذا خص المقاعد دون المقاوم، فقال له\n⟦2:836⟧\nعبد الله بن أبي: نقيم بالمدينة، فإن قاتلونا قاتلنا في الأزقة وإلا\nرجعوا عنا بالمذلة، وقال أكثرهم: نخرج إليهم، فدخل - صلى الله عليه وسلم - ولبس لأمته، وأعاد عبد الله قوله، فقال - صلى الله عليه وسلم -: \"ما كان لنبي أن يلبس لأمته ثم ينزعها حتى يقاتل \"\nفخرج النبي، وقوله: ﴿وَٱللَّهُ سَمِيعٌ عَلِيمٌ﴾⟪3:121⟫ أي سميع بما يقول مؤمنهم ومنافقهم، عالم بما ينوي كل منهم."}, {"a": [122], "v": 2, "p": 836, "ev": 2, "ep": 838, "sid": 1037, "t": "قوله تعالى: (إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون (122)\n⟦2:837⟧\nالهمة قد تكون عزما، وقد تكون حديث\nالنفس من غير أن يصير عزيمة، والفشل: الضعف الذي يكون من\nتحير الإنسان ظهر أو لم يظهر، وقد يقال لا يظهر من الإنسان من\nالإحجام فشل أيضا.\nوالطائفتان، قال المفسرون: هم بنو سلمة وبنو حارثة، لما رجع عبد الله هما بالرجوع،. ثم لم يفعلا،\n⟦2:838⟧\nوقوله: ﴿وَٱللَّهُ وَلِيُّهُمَاۗ﴾⟪3:122⟫ أي وليهما في أن عصمهما عن الانصراف، ووليهما في أن جازاهما إذ لم يفعلا ما هما به، وروي أنه لما نزل ذلك قالت الطائفتان: ما يسرنا أنا لم نهم بالذي هممنا، وقد أخبر الله أنه ولينا.\nونبه بقوله: ﴿وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ﴾⟪3:122⟫ أن التوكل على الله\nهو العاصم، وهو الفرض الأقصى من العباد في الدنيا."}, {"a": [123], "v": 2, "p": 838, "ev": 2, "ep": 839, "sid": 1039, "t": "قوله تعالى: (ولقد نصركم الله ببدر وأنتم أذلة فاتقوا الله لعلكم تشكرون (123)\nبدر: اسم ماء\n⟦2:839⟧\nكان لرجل يقال له: بدر، فسمي به، فصار ذلك الحرب\nمسمى به، وجعلهم أذلة لا على الحقيقة والمصدوقة، - فمن\nنصره الله فغير ذليل، ولكن على اعتبار العامة لقلتهم وقلة\nعدتهم، وهذه أيام تابع الله ذكرها وذكر المسلمين بعظم ما\nأولاهم فيها تثبيتا لقلوبهم، وتذكيرا بنعمه عليهم، وأمرهم\nبالتقوى المؤدية إلى شكرهم لها."}, {"a": [124, 125], "v": 3, "p": 840, "ev": 3, "ep": 845, "sid": 1041, "t": "قوله تعالى: (إذ تقول للمؤمنين ألن يكفيكم أن يمدكم ربكم بثلاثة آلاف من الملائكة منزلين (124) بلى إن تصبروا وتتقوا ويأتوكم من فورهم هذا يمددكم ربكم بخمسة آلاف من الملائكة مسومين (125)\nالكفاية: مقدار ما فيه سد خلة، والفرق بين الاكتفاء والاستغناء:\nأن الاكتفاء ما فيه سد الخلة وسع أو ضاق، والاستغناء ما فيه\n** السعة فهو أعم.\nوالإمداد: اتصال الشيء بالشيء، وأصله من مد الحبل\nوالمد يقال تارة في الماء، ومده ماء آخر، وتارة في السير.\nوالمدة امتداد الوقت، والمادة زيادة ممتدة، والمداد المد الذي هو\nالمكيال منه، والفور أصله من فارت القدر والتنور، والفور\n⟦3:841⟧\nمنهم من تصور منه الوجهة والعجلة، وإليه ذهب ابن عباس\nوالحسن وجماعة، ومنهم من تصور منه فوران الغضب.\nوإليه ذهب مجاهد والضحاك، والتسويم ترك الشيء وسومه،\n⟦3:842⟧\nومنه قيل: أسمت الإبل وسومته، والتسويم أيضأ إظهار\nسيماء في الشيء، وقد فسر المسومة على الأمرين.\nوقرئ: مسومة أي معلمة لأنفسها.\nوقد روي أنه نزلت الملائكة يوم بدر على خيل بلق، وعليهم عمائم. . . . . . . . . .\n⟦3:843⟧\nصفر، قال ابن عباس وغيره: عنى بذلك يوم بدر.\nقال: ولم تقاتل الملائكة إلا في ذلك اليوم، وقال الحسن: أمدهم\nبخمسة آلاف، لأنه عنى مع الأولين، وقال غيره: بل خمسة\nآلاف غير الثلاثة آلاف، وكانوا ثمانية آلاف، وقال بعضهم:\n⟦3:844⟧\nإنما أمدهم بألف، لقوله: ﴿فَٱسۡتَجَابَ لَكُمۡ أَنِّي مُمِدُّكُم بِأَلۡفٖ مِّنَ ٱلۡمَلَٰٓئِكَةِ﴾⟪8:9⟫\nولم يمدهم بخمسة آلاف، بل المسلمون قالوا: إن كرز بن جابر يمد المشركين. فأنزل الله ذلك تسكينا للمسلمين، ثم لم يمد المشركين.\nفلم يمد الله المسلمين بهم،\n⟦3:845⟧\nولهذا قال: ﴿وَيَأۡتُوكُم مِّن فَوۡرِهِمۡ﴾⟪3:125⟫."}, {"a": [126], "v": 3, "p": 845, "ev": 3, "ep": 846, "sid": 1046, "t": "قوله تعالى: (وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به وما النصر إلا من عند الله العزيز الحكيم (126)\nالضمير في قوله: (جعله) للإمداد والوعد، ونبه أنه إنما أراد بوعدهم\nوإمدادهم الملائكة نعمة عليهم، وهي مسرتهم وسكون\nجأشهم، فأما النصر في الحقيقة فليس إلا منه بلا حاجة إلى\nاستعانة، وفيه حث أن لا يبالوا بمن تأخر عن نصرتهم.\nوتنبيه أنه يعين تارة بالمدد وتارة بغير المدد، وأنه ناصر كل\nمنصور أينما كان، وممن كان، إذ هو المسبب لجميعه، والفاعل\n⟦3:846⟧\nالذي لا يستغني فاعل عنه، ثم وصف نفسه بالعزة والحكمة.\nتنبيها أن كل عز منه، وكل حكمة عنه."}, {"a": [127], "v": 3, "p": 846, "ev": 3, "ep": 847, "sid": 1047, "t": "قوله تعالى: (ليقطع طرفا من الذين كفروا أو يكبتهم فينقلبوا خائبين (127)\nالكبت: الصرع على الوجه والرد.\nوالخيبة: حرمان البغية. وتخصيص قطع الطرف من حيث\nإن نقص الأطراف من الشيء موصل إلى توهينه وإزالته، وعلى\nذلك قال: ﴿نَأۡتِي ٱلۡأَرۡضَ نَنقُصُهَا مِنۡ أَطۡرَافِهَاۚ﴾.\nوقال: ﴿قَٰتِلُواْ ٱلَّذِينَ يَلُونَكُم مِّنَ ٱلۡكُفَّارِ﴾⟪9:123⟫.\nوقيل: عنى بالأطراف\n⟦3:847⟧\nأعيانهم وصناديدهم.\nوقوله: (ليقطع) أي نصركم ليقطع، أو وما النصر إلا من عند الله، ليقطع."}, {"a": [128], "v": 3, "p": 847, "ev": 3, "ep": 849, "sid": 1048, "t": "قوله تعالى: (ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون (128)\nهو راجع إلى قوله: ﴿وَمَا ٱلنَّصۡرُ إِلَّا مِنۡ عِندِ ٱللَّهِ﴾⟪3:126⟫، أي ليس لك ولا لغيرك من هذا النصر شيء، وهو نجو\n⟦3:848⟧\nقوله: ﴿فَلَمۡ تَقۡتُلُوهُمۡ وَلَٰكِنَّ ٱللَّهَ قَتَلَهُمۡۚ﴾⟪8:17⟫\nوقال بعضهم: ليس للنبي - صلى الله عليه وسلم - أمر وإنما إليه.\nونبه أنك مأمور لا آمر، ومرتسم لا مرسم، قيل: بل أراد النبي - صلى الله عليه وسلم - أن يستغفر للمشركين.\nوقيل: بل أراد أن يدعو عليهم بالاستئصال لما كسروا رباعيته، فقال الله ذلك.\nوقوله: ﴿أَوۡ يَتُوبَ عَلَيۡهِمۡ﴾⟪3:128⟫ معطوف على قوله: (ليقطع).\nوقيل: بل معناه: إلا أن يتوب\n⟦3:849⟧\nأو يعذب، تنبيها أن أمرك تابع لأمر الله."}, {"a": [129], "v": 3, "p": 849, "ev": 3, "ep": 849, "sid": 1050, "t": "قوله تعالى : (ولله ما في السماوات وما في الأرض يغفر لمن يشاء ويعذب من يشاء والله غفور رحيم (129)\nبين بهذه الآية تحقيق ما قدمه بأنه هو المالك للكل، وله المشيئة في غفران من شاء وتعذيب من شاء."}, {"a": [130], "v": 3, "p": 849, "ev": 3, "ep": 852, "sid": 1050, "t": "قوله تعالى: (يا أيها الذين آمنوا لا تأكلوا الربا أضعافا مضاعفة واتقوا الله لعلكم تفلحون (130)\nإن قيل: ما اتصال هذه الآية بما قبلها؟\nقيل: إنه لما نهى عن الكفر فيما تقدم، وقبح صورته.\nوحذر منه، وبين قدرته عليهم حث قال: ﴿وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ﴾⟪3:129⟫ نهى هاهنا عن تعاطي أفعال الكفرة، وقد\n⟦3:850⟧\nتقدم الكلام في قبح الربا، وأما أكله أضعافا فقد قال عطاء\nومجاهد هو أنهم كانوا في الجاهلية إذا باعوا أو أقرضوا إلى مدة\nثم تأخر القضاء زادوا على أصل المال لزيابة الأجل\nالمضروب.\nإن قيل: لم قال: ﴿أَضۡعَٰفٗا مُّضَٰعَفَةٗۖ﴾⟪3:130⟫ فجمع بين اللفظتين؟\n⟦3:851⟧\nقيل: قال بعضهم ذلك للتأكيد.\nوقيل مضاعفة من الضعف لا من الضعف، ومعناه ما تعدونه ضعفا\nهو ضعف، أي نقص، كقوله: ﴿وَمَآ ءَاتَيۡتُم مِّن رِّبٗا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ﴾⟪30:39⟫ وقوله: ﴿يَمۡحَقُ ٱللَّهُ ٱلرِّبَوٰاْ﴾⟪2:276⟫.\nومن هذا أخذ بعض المحدثين:\nزيادة شيب وهي نقص زيادتي. . . وقوة جسم وهي من قوتي ضعف.\n⟦3:852⟧\nثم حث على تقوى الله، وذكر أن ببلوغها ترجون الفلاح.\nواستدل بعض الحنفية بهذه الآية على فساد بعض ما يدعيه الشافعية\nمن دلالة الخطاب، فقال: لو كان ذلك صحيحا لكان يجوز أكل\nالربا إذا لم يكن أضعافا، وهذا لأن يكون دلالة عليهم أولى.\nلأنه لما زهدنا في الكثير منه فلأن نزهد في القليل أولى، على أن\nالقضية بذلك على مقتضى العموم، فمجيء ما ترك دلالة خطابه\nفي بعض المواضع لا يفسد هذا الأصل، كمجيء لفظ عام ترك\nعمومه، وتكرير النهي عن الربا تفظيع لأمره، وتقبيح لشأنه."}, {"a": [131, 132], "v": 3, "p": 853, "ev": 3, "ep": 854, "sid": 1054, "t": "قوله تعالى: (واتقوا النار التي أعدت للكافرين (131) وأطيعوا الله والرسول لعلكم ترحمون (132)\nإعداد الشيء تهيئته قبل الحاجة إليه.\nوإنما أراد تقديره وإيجاده، فلا حاجة به تعالى إلى الإعداد.\nوأصله من العد، وقولك: أعددت كذا لكذا ، أي اعتبرت قدره\nبقدره.\nإن قيل: ما وجه ذكر اتقوا النار بعد قوله: ﴿ٱتَّقُواْ ٱللَّهَ﴾؟\nقيل: قد تقدم أن قوله: ﴿ٱتَّقُواْ ٱللَّهَ﴾ يقال باعتبار\nذاته، واتقوا النار باعتبار عقابه، فالأول للأولياء الأصفياء.\nولذلك وصله بالفلاح الذي هو أعلى درجة الثواب.\nوالثاني للمذنبين، فلذلك وصله بالرحمة، ولما كانت المنزلة\nالأولى لا تحصل إلا لمن حصلت له المنزلة الثانية، حث كافة\n⟦3:854⟧\nالناس على الاستعانة بتقوى عقوبته، والطاعة له ولرسوله في ترك\nالربا وغيره من المعاصي؛ ليصلوا إلى الرحمة ذريعة إلى الفلاح.\nإن قيل: الفلاح لا يخرج من أن يكون رحمة؟\nقيل: صحيح، ولكن الرحمة أعم من الفلاح، فكل فلاح رحمة، وليس كل رحمة فلاحا، ومن قال في قوله: ﴿أُعِدَّتۡ لِلۡكَٰفِرِينَ﴾⟪3:131⟫ دلالة أن لا فاسق فيها، فليس باستدلال يوجب الركون إليه، لأن ما يصح أن يشترك فيه أقوام إذا\nقيل: أعد لفلان. فليس فيه أنه لم يعد لغيره.\nثم قد ثبت أن النار دركات، فأكثر ما في ذلك أن النار المعدة للكافر ليست للفاسق."}, {"a": [133], "v": 3, "p": 854, "ev": 3, "ep": 858, "sid": 1055, "t": "قوله تعالى: (وسارعوا إلى مغفرة من ربكم وجنة عرضها السماوات والأرض أعدت للمتقين (133)\nإن قيل: ما الفرق بين\n⟦3:855⟧\nالطول والعرض؟ وهل هما على تقديرك ووضعك كالصعود\nوالحدور، أم هما شيئان مختلفان بالذات؟ وذاك أن الطول\nوالعرض من خواص الجسم، فالطول معتبر بالجانب الذي منه\nينشأ وإليه ينشأ. والعرض بالجانبين الآخرين، وذلك متصور في\nالحائط والثوب والبيت، وقد يقال ذلك باعتبار الوضع في أشياء\nكثيرة، وقد وقع شبهة على من لم يتمهر في المعقولات، ولم\nيتجاوز منزل المحسوسات، وقال: إذا كانت الجنة في السماء\nالرابعة على ما روي في الخبر فكيف يكون عرضها عرض\nالسموات؛ فجاء قوم من اليهود إلى الرسول - صلى الله عليه وسلم - فقالوا: إذا كانت الجنة عرضها السموات والأرض فأين النار؟\nفأجابهم - صلى الله عليه وسلم - فقال: \"سبحان الله إذا جاء النهار فأين الليل \"؟،\n⟦3:856⟧\nوهذه معارضة تقنع العامة بما فيه المقنع، وتطلع الخاصة على ما\nنبه عليه بقوله: \"ما لا عين رأت، ولا أذن سمعت \"\nوقد روي عن ابن عباس: أن لله عوالم، هذا أحدها.\n⟦3:857⟧\nوقال أبو مسلم بن بحر: العرض هاهنا من قولهم: عرضت الشيء\nبالشيء في البيع، وذلك قائم مقام المساواة.\nوالمعنى: لو عرضت الجنة بالسموات والأرض لكانتا ثمنا لها، وذلك\n⟦3:858⟧\nيفسده قوله في غير هذه الآية: ﴿كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾⟪57:21⟫.\nوقال بعضهم: هو من قولهم: فلان في جاه عريض، وفي سعة\nورحب، وقد يقال للكبير عريض، نحو: ﴿فَذُو دُعَآءٍ عَرِيضٖ﴾⟪41:51⟫.\nوالمغفرة أصلها إزالة العقوبة، وإن كان قد يقال لها وللإعطاء.\nولما أمر تعالى بالاتقاء من النار، والاتقاء منها مقتض\nللمغفرة، وذلك منزلة التاركين للذنب، أمره في هذه الآية أن لا\nيقتصر على التقوى من النار، التي هي مقتضية للمغفرة، بل\nيتجاوز إلى طلب الجنة، فقال: ﴿وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ﴾⟪3:133⟫."}, {"a": [134], "v": 3, "p": 859, "ev": 3, "ep": 863, "sid": 1060, "t": "قوله تعالى: (الذين ينفقون في السراء والضراء والكاظمين الغيظ والعافين عن الناس والله يحب المحسنين (134)\nالسراء والضراء إشارة إلى حالي السعة والضيق، كاليسر\nوالعسر، وإلى حالي السرور والاغتمام، وقد فسر بهما.\nواللفظ يتناولهما، فإن السراء يقابلها الغم، والضراء يقابلها\nالنفع، فأخذ اللفظان المختلفا التقابل ليدل كل واحد على\nمقابله، وهذا من دقائق إيجازات البلاغة، فمن نظر إلى معنى\nالسراء قال السرور والغم، ومن نظر إلى معنى الضراء قال النفع\nوالضر، ولما كان الناس في الإنفاق أربعة أضرب:\nضرب لا ينفق في حالي السعة والضيق، وهو اللئيم على الإطلاق.\nوضرب ينفق في حالي الضيق دون السعة، كما قال الشاعر:\nوكان غني النفس في حال فقره. . . فصار فقيرا في الغنى خيفة الفقر\n⟦3:860⟧\nوضرب ينفق في السعة دون الضيق، وهو من وجه جبان يخاف\nالفقر، ومن وجه حازم يأخد بالوثيقة في أمور الدنيا، وضرب ينفق في\nالحالين، وذلك أحد رجلين: إما متهور لا يتفكر في العواقب، ولا\nيبالي من أين يأخذ وأين يضع، وذلك هو الموصوف بأنه من إخوان\nالشياطين، وإما واثق بكفاية الله ينفق ما يحصل في يده اعتمادا على\nخزائن ربه، لكن لا يتناول إلا من حيث ما يجب وكما يجب، ولا يضع\nإلا كذلك، وهو الذي يتناول كل آية مدح فيها المنفقون.\nوكظم الغيظ: هو الحلم، فقد قيل: الحلم: كظم الغيظ، وهو والعفو\nمنزلتان شريفتان، ولهذا قال - صلى الله عليه وسلم -: \"من كظم الغيظ وهو يقدر أن ينفذه خيره الله في أي الحور شاء\".\n⟦3:861⟧\nوقال تعالى: ﴿وَلۡيَعۡفُواْ وَلۡيَصۡفَحُوٓاْۗ﴾⟪24:22⟫، وقال: ﴿وَأَن تَعۡفُوٓاْ أَقۡرَبُ لِلتَّقۡوَىٰۚ﴾⟪2:237⟫، وقال - صلى الله عليه وسلم -:\n\"ينادي يوم القيامة مناد: من كان له أجر على الله فليقم، فيقوم العافون عن الناس \"، ثم تلا هذه الآية.\nوالفرق بين الحلم والعفو، أن الحلم راجع إلى حال\nالإنسان في نفسه، والعفو إلى ما بينه وبين غيره، وإن كان قلما\nينفك أحدهما عن الآخر، ووجه الآية أن الله حث في الآية الأولى\n⟦3:862⟧\nعلى طلب الجنة المعدة للمتقين، ثم بين حالهم وأفعالهم، فذكر\nما دل على جماع مكارم الأخلاق، وهو السخاء في حالي السراء\nوالضراء والحلم والعفو، وذلك أشرف ضربي الشرع، وذاك أن الشرع\nضربان: أحكام ومكارم، ولن يستكمل الإنسان مكارمه إلا بعد أن\nيستكمل أحكامه، فإن تحري أحكام الشرع من باب العدل، وتحري\nالعدالة فرض، ومكارمه من باب الإحسان، أي التفضل، وتحري\nالتفضل نفل، ولا تقبل نافلة من أهمل الفرض، ولا يفضل من\nترك العدل، بل لا يصح تعاطي التفضل إلا بعد العدل، فإن العدل\nفعل ما يجب، والفضل الزيادة على ما يجب، وكيف تصح الزيادة\nعلى الشيء الذي هو غير حاصل في ذاته، وبين تعالى أن من تخصص\nبمكارم الشرع فهو محسن، والله يحب المحسنين، وإحسان العبد ومحبته\nالله إياه هو أن يرى متخصصا بعامة أوصاف الله على غاية وسع\n⟦3:863⟧\nالبشر، فيصدق عليه أن يقال: هو جواد وكريم وحليم، وودود\nإلى سائر ما يصح أن يوصف به أولياء الله."}, {"a": [135, 136], "v": 3, "p": 863, "ev": 3, "ep": 869, "sid": 1064, "t": "قوله تعالى: (والذين إذا فعلوا فاحشة أو ظلموا أنفسهم ذكروا الله فاستغفروا لذنوبهم ومن يغفر الذنوب إلا الله ولم يصروا على ما فعلوا وهم يعلمون (135) أولئك جزاؤهم مغفرة من ربهم وجنات تجري من تحتها الأنهار خالدين فيها ونعم أجر العاملين (136)\nالفاحشة: ما تناه قبحه مما يدرك بالبصر أو بالبصيرة ، ولكونها\nمستعملة فيهما قيل: فلان فاحش الطول. اعتبارا باستقباح\nالبصر إياه، وقيل للزنى والبخل المتناهي: فاحشة. اعتبارا\nباستقباح البصيرة إياهما، ويقال: فلان ظلم نفسه. على ثلاثة أوجه:\n⟦3:864⟧\nأحدها: إذا جنى على نفسه جناية لا يتخطاها.\nوالثاني: إذا ظلم ذويه الذين هم بمنزلة نفسه.\nوعلى نحو ذلك قال الشاعر فيمن ظلم ذويه:\nوما كنت إلا مثل قاطع كفه. . . بكف له أخري فأصبح أجذما\nوعلى هذا الوجه قد يقال ذلك فيمن ظلم واحدا من كافة الناس.\nإذا كان الناس كنفس واحدة وآحادهم كأعضائها.\nوالثالث: أن ظلم الإنسان غيره لما كان وباله راجعا إليه.\nيقال فيمن ظلم غيره:\nقد ظلم نفسه، وعامة ما ذكر تعالى: ظلموا أنفسهم.\nذكره مقرونا بنفي ظلمه تعالى إياهم، نحو: ﴿إِنَّ ٱللَّهَ لَا يَظۡلِمُ ٱلنَّاسَ شَيۡـٔٗا وَلَٰكِنَّ ٱلنَّاسَ أَنفُسَهُمۡ يَظۡلِمُونَ﴾⟪10:44⟫، وقد ذكر حيث نهى\nعن ظلم الغير تنبيها على المعنى المتقدم، نحو قوله: ﴿وَلَا تُمۡسِكُوهُنَّ ضِرَارٗا لِّتَعۡتَدُواْۚ﴾⟪2:231⟫، ثم قال: ﴿وَمَن يَفۡعَلۡ ذَٰلِكَ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ﴾⟪2:231⟫\n⟦3:865⟧\nوالإصرار: الإقامة على القبيح. مأخوذ - من الصرار\nوالصرة، كأن المصر على الذنب جعل ذنبه مصرورا على نفسه.\nأي معقودا لا يجد سبيلا إلى حله.\nوقوله: ﴿وَهُمۡ يَعۡلَمُونَ﴾⟪3:135⟫ في موضع الحال، أي لم يكن منهم إصرارا مع العلم، واشتراط العلم أنه قد يعذر الإنسان مع الجهل في ارتكابه بعض المآثم.\nكمن تزوج أخته من الرضاعة وهو لا يعلم ذلك، وهذه الآية\nمع الأولى مشكلة، يقال: هل قوله: ﴿وَٱلَّذِينَ إِذَا فَعَلُواْ﴾⟪3:135⟫ صفة للمتقين\nكقوله: ﴿ٱلَّذِينَ يُنفِقُونَ﴾⟪3:134⟫ أم استئناف حكم؟ ولم أعيد\nذكر الجنة منكرا مقرونا بوصف آخر؟ ووجه ذلك أن الله تعالى\n⟦3:866⟧\nلما أمر الناس بتقواه وتقوى ناره أولا، وأمرهم بالمسارعة إلى\nالمنزلتين أولا: إلى طلب المغفرة التي يستحقها المتقي من النار، ثم\nإلى الجنة العريضة التي يستحقها المتقي من الله، ذكر بقوله: ﴿ٱلَّذِينَ يُنفِقُونَ فِي ٱلسَّرَّآءِ وَٱلضَّرَّآءِ﴾⟪3:134⟫ حال المتقين لله، المستحقين لتلك الجنة.\nوقال: هم الذين تجاوزوا تعاطي أحكام الشرع إلى تعاطي\nمكارمه، والذين اقتدوا بالله على غاية جهدهم في اكتساب\nصفاته، ثم ذكر حال المستغفرين لوقوع فاحشة منهم أو\nظلم، وبين أن لهم جنات أدون من تلك الجنة، فقال: الذين إذا\nأخلوا بشيء من الواجبات ذكروا الله فأقلعوا، كقوله: ﴿إِنَّ ٱلَّذِينَ ٱتَّقَوۡاْ إِذَا مَسَّهُمۡ طَٰٓئِفٞ مِّنَ ٱلشَّيۡطَٰنِ تَذَكَّرُواْ فَإِذَا هُم مُّبۡصِرُونَ﴾⟪7:201⟫\n⟦3:867⟧\nولم يستمروا على فعل الشر، ثم قال: ﴿وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ﴾⟪3:135⟫ على سبيل الاعتراض بينه وبين تمام الكلام؟\nتنبيها أن الإنسان لا يجب أن يلتجئ إلا إلى الله، وبين أنه\nمن فعل ذلك لم يقتصر تعالى معه على ترك الذنب عليه، بل\nيجعل له جنات، وجعل هذه الجنات على أوصاف يتصورها\nالوهم، ويدرك مثلها الحس، وجعل للفرقة الأولى جنة لا\nيتصورها الوهم، ولا يحيط بها الحس، فإن جنة عرضها\nالسموات والأرض مع كونها في السماء إشارة إلى ما قاله - صلى الله عليه وسلم -:\n\"ما لا عين رأت \"، وذلك مما لا يتصوره الوهم، ولا كانت\nالفرقة الأولى عاملت أنفسهم وعباد الله بضرب عامل الله به عباد الله\nوهو الجود والحلم والعفو، سماهم هو تعالى بما استحقه، وهو\nالمحسن، وقابلهم بمقابلة يطلبها هو من العباد أن يقابلوه بها.\nوهي المحبة، فقال: ﴿وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾⟪3:134⟫\nوالفرقة الثانية: عاملت أنفسها وعباد الله بما لا يصح أن يوصف الله به.\nبل يوصف به العبد المتدارك لتقصيره، جعلهم من العملة\n⟦3:868⟧\nالمستحقة للأجر، وسمى نفسه حيث ذكر مقابلة الفرقة\nالأولى فقال: ﴿وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾⟪3:134⟫، وهو أعم الأسماء\nوأخصها به، تنبيها أنهم يراعونه بالإلهية، وسمى نفسه\nحيث ذكر مقابلة الفرقة الثانية ربهم، تنبيها أنهم يراعونه\nبالنعمة الواصلة إليهم، التي هي سبب تربيتهم، وعلم أن\nمنزلة الفرقة الأولى منزلة الشاكرين الموصوفين بقوله:\n﴿وَسَنَجۡزِي ٱلشَّٰكِرِينَ﴾⟪3:145⟫، ومنزلة الفرقة الثانية منزلة\nالصابرين الموصوفين بقوله: ﴿إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ﴾⟪39:10⟫، فذكر في الشاكرين المجازاة الجارية بين الأحباء، وذكر في الصابرين الأجرة كفاء ما يجعل للأجراء، وإن كان قد جعلها بلا حساب، وشتان ما بين الأجير والحبيب، وهذه من المواضع التي لم أر من تحرى مذهب\nالتحقيق، واشتغل به مع صعوبته، غير أن ابن بحر لما انتهى\nإلى قوله: ﴿أُوْلَٰٓئِكَ جَزَآؤُهُم﴾⟪3:136⟫، قال: إن المغفرة المذكورة\n⟦3:869⟧\nهي المذكورة في قوله: ﴿وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ﴾⟪3:133⟫\nوكذلك الجنات هي الجنة التي عرضها السموات، وإن ذلك أجرتهم بتلك الأفعال، وهو مع أنه لم يتدبر التفصيل واختلاف المجازين والجزائين وأوصافها لم يتفكر في أن الفكرة إذا أعيد ذكرها تعاد معرفة،، وإلا كان الثاني غير الأول، فلو كانت المغفرة والجنات هي التي تقدم ذكرها لقال المغفرة والجنات."}, {"a": [137], "v": 3, "p": 869, "ev": 3, "ep": 872, "sid": 1070, "t": "قوله تعالى: (قد خلت من قبلكم سنن فسيروا في الأرض فانظروا كيف كان عاقبة المكذبين (137)\nالخلاء: المكان الذي لا ساتر فيه، من بنية وغيرها، وقد يقال للمكان الذي لا ساكن فيه، وخليته تركته في خلاء، ثم يقال لكل ترك: تخلية حتى\nقيل: ناقة خلية: مخلاة عن الحلب، وامرأة خلية مخلاة عن\nالزوج، وسميت السفينة المتروكة تمر بذاتها خلية، وزمان خال\nأي ماض، كأنه خلا عما كان فيه، وأصل السنة من السني أي\n⟦3:870⟧\nصب الماء على وجه الأرض، وعلى التشبيه به قيل: سننت\nالدرع، ووجه مسنون، والسنة: الطريقة المجعولة للاقتداء\nبها محسوسة كانت أو معقولة، وعني بالسنة هاهنا ما كان من\nالقرون الأولى، أخيارهم وأشرارهم، وما كان في مقابلتهم\n⟦3:871⟧\nمنه تعالى ومجازاته إياهم إن خيرا فخيرا، وإن شرا فشرا في الدنيا\nتارة وفي الآخرة تارة، على ما بينه تعالى بكلامه، وشوهد من\nأحكامه، فنبهنا على اعتبار ما جرى به سننه، وأمرنا بالسير في\nالأرض والنظر إليه، ولم يعن بالسير السعي بالأرجل، ولا\nبالنظر نظر العين، فذلك غير مغن بانفراده في معرفة سنة الله في\nالذين خلوا، وإنما عنى إجالة الخاطر فيها، والنظر بالبصيرة\nللمتحرين للحكم، والمنبهين على العبر، وعلى هذا قوله:\n﴿أَوَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ﴾، وقوله: ﴿فَٱمۡشُواْ فِي مَنَاكِبِهَا﴾⟪67:15⟫، وقد\n⟦3:872⟧\nحمل بعض الصوفية قوله - صلى الله عليه وسلم - \"سافروا تغنموا\" على هذا."}, {"a": [138], "v": 3, "p": 872, "ev": 3, "ep": 873, "sid": 1073, "t": "قوله تعالى: (هذا بيان للناس وهدى وموعظة للمتقين (138)\nجعل تعالى القرآن بيانا للعامة والخاصة، فلهذا قال للناس لأنه\nما من ذي فكرة استمع إليه إلا حصل منه بيان ما، وجعله هدى\nوموعظة للمتقين خاصة، وقد تقدم الكلام في تخصيصه هدى\nلهم في قوله: ﴿هُدٗى لِّلۡمُتَّقِينَ﴾⟪2:2⟫، فالفرق بين الهدى والموعظة:\nأن الهدى يقال باعتبار معرفة الشريعة وسلوك طرقها إلى ثواب\nالله تعالى، والوعظ يقال باعتبار معرفة الثواب والعقاب، إن\n⟦3:873⟧\nقيل: أيراد بذلك أنهم يهتدون ويتعظون، أم انهم يهدون ويعظون؟\nقيل: يحتمل الوجهين، ويضح حمله عليهما، فهم\nفي الحقيقة يهتدون به ويتعظون، ويهدون به غيرهم ويعظون."}, {"a": [139], "v": 3, "p": 873, "ev": 3, "ep": 876, "sid": 1074, "t": "قوله تعالى: (ولا تهنوا ولا تحزنوا وأنتم الأعلون إن كنتم مؤمنين (139)\nالوهن والوهي يتقاربان، لكن الوهن ضعف، والوهي يقال فيه وفي التخرق، فهو أعم.\nوالحزن: ألم موجع للنفس من فوت مطلوب أو فقد محبوب.\nإن قيل: كيف أمر\n⟦3:874⟧\nالإنسان بأن لا يهن ولا يحزن، وليس ذلك باختياره، بل هو شيء\nيعرض له بالاضطرار؟\nقيل: النهي في الحقيقة متوجه إلى تعاطي فعل ما يورث ذلك، وإن كان في اللفظ متناولا للحزن والوهن، وذلك أن الحزن يعرض بأن لا يستشعر الإنسان ما عليه جبلت الدنيا.\nولا يعرف أن أموالنا وأبداننا عارية مستردة، ولا يحتمل صغار\nالمكاره، فيتوصل بها إلى احتمال ما هو أعظم منها، وعلى هذا\nقوله: ﴿لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ﴾⟪57:23⟫.\nوقوله: ﴿وَأَنتُمُ ٱلۡأَعۡلَوۡنَ﴾⟪3:139⟫: قيل: عنى في الاستقبال إشارة إلى\nنحو قوله: ﴿وَٱلۡعَٰقِبَةُ لِلۡمُتَّقِينَ﴾، فيكون هذا وعدا لهم،\n⟦3:875⟧\nوقيل: أراد في الحال فإنهم الأعلون بالحجة ورجاء المعفرة.\nإشارة إلى نحو قوله: ﴿إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ﴾⟪4:104⟫ ومثله: ﴿لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ﴾⟪20:68⟫.\nوسبب نزول ذلك، قيل: هو أن النبي - صلى الله عليه وسلم -\nأمر بطلب القوم بعد يوم أحد، وقال: \"لا يخرج معنا إلا من شهدنا\nبالأمس \"، فاشتد على المسلمين، وقالوا: فينا جرحى، فأنزل الله\nتعالى ذلك، ونبه بقوله: ﴿إِن كُنتُم مُّؤۡمِنِينَ﴾⟪3:139⟫ أن من شرط\n⟦3:876⟧\nالإيمان رفض الوهن والحزن وأنتم مؤمنون، فواجب أن لا تهنوا\nولا تحزنوا سيما والعلو لكم."}, {"a": [140], "v": 3, "p": 876, "ev": 3, "ep": 881, "sid": 1077, "t": "قوله تعالى: (إن يمسسكم قرح فقد مس القوم قرح مثله وتلك الأيام نداولها بين الناس وليعلم الله الذين آمنوا ويتخذ منكم شهداء والله لا يحب الظالمين (140)\nالفرق بين المس واللمس:\nأن اللمس أخص، فإنه بالحاسة، والمس به وبغيره، وهو ههنا\n⟦3:877⟧\nعبارة عن الإصابة والقرح أعم من الجرح، فإن الجرح إصابة\nالجارحة في الأصل، والقرح يقال له ولما يحدث من ذاته، نحو\nقرح البعير إذا خرج به قرحة، وهي شبه جرب.\nوالقرح مصدر ثم يسمى المقروح قرحا.\nوالقرح الاسم، وقال بعض أهل اللغة: القرح: الجراحة.\nوالقرح: ألمها.\nوالدول والدور يتقاربان، لكن الدور أعم، فإن الدولة لا تقال إلا في الحظ الدنيوي،\n⟦3:878⟧\nوكذلك الجد، ولهذا قيل: \"لا ينفع ذا الجد منك الجد\"\nأي الحظوظ الدنيوية غير نافعة في القيامة،، نحو: ﴿يَوۡمَ لَا يَنفَعُ مَالٞ وَلَا بَنُونَ﴾⟪26:88⟫، وقوله: ﴿وَلِيَعۡلَمَ ٱللَّهُ﴾⟪3:140⟫ قيل ليعرف، ولهذا تعدى إلى مفعول واحد.\nوقيل: إن مفعوله الثاني محذوف ومتى قيل في الله: إنه علم كذا أو لم يعلمه، فليس القصد إلى إثبات علمه أو نفيه.\nوإنما القصد إلى إثبات ذلك الشيء أو نفيه، وإذا استعمل في غيره\n⟦3:879⟧\nفإنه يقال على الوجهين، وأما الشهداء فقد قيل: هم المذكورون\nفي قوله ﴿لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ﴾⟪2:143⟫.\nوقال الحسن وقتادة: عنى بها المقتولين في الحرب، وسموا بذلك لقوله: (ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء عند ربهم يرزقون (169) الآية،\n⟦3:880⟧\nلما جعلهم أحياء عند ربهم سموا شهداء، وأصل ذلك أن غاية ما\nيستحقه الإنسان في الآخرة القرب من الله، وكونه عنده، ولما\nوعد الله القتيل في سبيله بذلك سمي شهيدا، ونبه تعالى بالآية أنه\nغير إنصاف لمن ساوى العدو في المغالبة الدنيوية أن يحزن، فكيف\nبمن كان غالبا، وبين بقوله: ﴿وَتِلۡكَ ٱلۡأَيَّامُ نُدَاوِلُهَا﴾⟪3:140⟫ أن\nمن حق العاقل أن لا يبالي بما يفوته مالا كان أو جاها أو قهرا.\nفإن الله جعل بنية الدنيا على أن تكون أعراضها دولا بين أخيارهم\nوأشرارهم، وليصبر الأخيار فيما يصيبهم من المحن، ويشكروا\nما ينيلهم من المنح، فيصلوا بذلك إلى ثوابه، وعلى ذلك\n﴿وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ﴾⟪47:31⟫\nإن قيل: هل يصح أن تكون الدولة للكافرين على المؤمنين؟\nقيل: يجوز ذلك إذا كانت الدولة من الحظوظ الدنيوية، التي قد يعطى الكافر منها أكثر مما يعطى المؤمنون، قال قتادة: ولولا الدولة ما أوذي المؤمنون،\n⟦3:881⟧\nلكن قد يدال الكافر من المؤمن، ويبتلى المؤمن بالكافر، ليتميز\nالمطيع من العاصي، وقد حكم تعالى في كل ذلك أن الغلبة\nللمؤمنين في الحقيقة بقوله: ﴿فَإِنَّ حِزۡبَ ٱللَّهِ هُمُ ٱلۡغَٰلِبُونَ﴾⟪5:56⟫.\nوفي قوله: ﴿وَٱللَّهُ لَا يُحِبُّ ٱلظَّٰلِمِينَ﴾⟪3:140⟫، تنبيه أنه لا ينصر الكافرين\nفي الحقيقة، وإن تصور بعض الناس ما يعطيهم في بعض\nالأحوال نصرة منه، تنبيه أنه لا يظلم، فمحال أنه مع حكمه بأنه\nلا يحب الظالمين يفعل فعلهم."}, {"a": [141], "v": 3, "p": 881, "ev": 3, "ep": 883, "sid": 1082, "t": "قوله تعالى: (وليمحص الله الذين آمنوا ويمحق الكافرين (141)\nالمحص كالفحص، لكن الفحص يقال في إبراز الشيء من\n⟦3:882⟧\nخلال أشياء منفصلة عنه، والمحص في إبرازه عن أشياء متصلة به.\nقال الخليل: التمحيص: التخليص، عن العبث، يقال:\nمحص عنا ذنوبنا، والمحق هو إبطال الشيء حالا فحالا.\n⟦3:883⟧\nوالقصد بتمحيص المؤمن ما ذكره في قوله: ﴿إِنَّمَا يُرِيدُ ٱللَّهُ لِيُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَيۡتِ وَيُطَهِّرَكُمۡ تَطۡهِيرٗا﴾⟪33:33⟫.\nوقوله: ﴿وَلِيُمَحِّصَ مَا فِي قُلُوبِكُمۡۚ﴾⟪3:154⟫ وعلى معنى المحص ما ورد من لفظ\nالفتنة والابتلاء، والقصد بمعني الآية أن المؤمن والفاسق كسبيكتي\nذهب: إبريز كلف، وبهرج من خزف إذا فتنا خلص\nالإبريز، وانمحق البهرج، فكما أن السبك سبب لاختيار الإبريز\nوإعداده في خاص الخزانة، وسبب لاجتواء البهرج وطرحه\nبالمبعد، كذا التكليف سبب لاصطفاء المؤمن لكريم جواره، وطرد\nالكافر إلى حرق ناره، كما قال في المؤمنين. ﴿فِي مَقۡعَدِ صِدۡقٍ عِندَ مَلِيكٖ مُّقۡتَدِرِۭ﴾⟪54:55⟫، وقال في الكافرين: ﴿كـَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ﴾⟪83:15⟫."}, {"a": [142], "v": 3, "p": 884, "ev": 3, "ep": 888, "sid": 1085, "t": "قوله تعالى: (أم حسبتم أن تدخلوا الجنة ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين (142)\nمعنى أم حسبتم: لا تحسبوا، واستعارة الاستفهام للنهي، مبالغة في المعنى،\n⟦3:885⟧\nو (أم): على وجهين: معادلة للألف، ولاستئناف استفهام، ويفسر ببل، ومن النحويين من قال: لا تنفك من أن تكون تابعا للألف.\nإما ملفوظا به أو مقدرا، وقال: وتقدير الكلام ههنا لما ذكر قوله:\n﴿وَلَا تَهِنُواْ وَلَا تَحۡزَنُواْ﴾⟪3:139⟫ أعلمتم ذلك ﴿أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ﴾⟪3:142⟫.\nوقد تقدم أن كل موضع نفي فيه علم الله فإنما هو نفي\nلما يتعلق به، ويدل على صحة ذلك قولهم: ما علمت أحدا\n⟦3:886⟧\nيخرج إلا زيد، فجاز الرفع في زيد لما كان معناه ما يخرج أحد فيما\nعلمت إلا زيد، وأما قوله: (ويعلم) فمنصوب على الصرف،\n⟦3:887⟧\nوقد قرئ (ويعلم الصابرين) بالجزم، والفرق بين العطف\nوالنصب على الصرف هو أنه إذا كان عطفا يراد حصول الفعلين\nمجتمعين كانا أو مفترقين، وإذا نصب فالمراد حصول الفعلين\nمعا، ونفيهما معا، على ذلك قول الشاعر:\nلا تنه عن خلق وتأتي مثله. . .\nمعناه لا تجمع بين الأمرين معا، ويحتمل أن يكون (ويعلم)\n⟦3:888⟧\nمعطوفا على قوله: ﴿أَن تَدۡخُلُواْ ٱلۡجَنَّةَ﴾⟪3:142⟫، وذاك أنه لما ضمن\nللصابرين دخول الجنة في غير موضع، بين ههنا أن لا يدخلوها\nمحكوما لهم بالصبر، ولما يجاهدوا، إذ كان الصبر لا يثبت إلا\nبمجاهدة النفس، ولم يعن بالمجاهدة الجهاد في حرب الكفار\nفقط، بل أراد ذلك ومجاهدة الشيطان والنفس المدلول عليها\nبقوله - صلى الله عليه وسلم - \"جاهدوا أهواءكم كما تجاهدون أعداءكم \"، ونحو هذه الآية قوله: ﴿وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ﴾⟪47:31⟫."}, {"a": [143], "v": 3, "p": 888, "ev": 3, "ep": 891, "sid": 1089, "t": "قوله تعالى: (ولقد كنتم تمنون الموت من قبل أن تلقوه فقد رأيتموه وأنتم تنظرون (143)\nسبب نزولها أن قوما لم يحضروا بدرا كانوا يقولون: ليت لنا يوما مثله، حتى نجاهد.\n⟦3:889⟧\nوقيل: سببه أن قوما سألوا النبي - صلى الله عليه وسلم - أن يأذن لهم أن يأتوا المشركين في رحالهم ويقاتلوهم، فقال - صلى الله عليه وسلم -:\n\"لم أؤمر بذلك \".\nوالموت عبارة عن الحرب، كقول الشاعر:\nإذا استنزلوا عنهن للطعن أرقلوا. . . إلى الموت إرقال الجمال المصاعب\nوأراد أنكم تمنيتم الحرب فلم تحيرتم؟ والنظر يكنى به عن\nالتحير، نحو:\n⟦3:890⟧\n. والموت خزيان ينظر\nوقيل: وأنتم تنظرون إلى النبي - صلى الله عليه وسلم - لكونه بين أظهركم، وذلك تبكيت لهم، وقول النحويين: أراد بالموت سببه، فحذف\nالمضاف، فقريب، وقول أبي علي الجبائي: إنه لا يجوز أن\n⟦3:891⟧\nيتمنوا قتل المشركين لهم، \"فإن قتل المشركين لهم كفر بالله، ولا\nيجوز للمؤمن أن يتمنى الكفر بالله، وإنما تمنوا الموت الذي هو\nفعل الله في الحال، التي يكون فيها أبعد من العاصي، فهذا تحيل\nلمراد القوم إنما تمنوا حربا ليبلوا فيها بلاء حسنا."}, {"a": [144], "v": 3, "p": 891, "ev": 3, "ep": 892, "sid": 1092, "t": "قوله تعالى: (وما محمد إلا رسول قد خلت من قبله الرسل أفإن مات أو قتل انقلبتم على أعقابكم ومن ينقلب على عقبيه فلن يضر الله شيئا وسيجزي الله الشاكرين (144)\nروي أنه لما كان يوم أحد نادى مناد: قتل محمد، فقال قوم: علام نقاتل وقد قتل رسول الله؟! فأنزل الله ذلك.\nوالإشارة بالمعنى إلى ما قال أبو بكر لما مات النبي - صلى الله عليه وسلم - من كان يعبد محمدا فإنه قد مات، ومن كان\n⟦3:892⟧\nيعبد الله فإن الله حي لا يموت، أيها القوم إن الله قد نعى إليكم\nنبيكم \" ثم تلا الآية، ولفظ الاستخبار يتناول: (انقلبتم).\nوقوله: ﴿فَلَن يَضُرَّ ٱللَّهَ شَيۡـٔٗاۚ﴾⟪3:144⟫ تعريض بهم بأنهم يضرون أنفسهم.\nإن قيل: كيف تعلق قوله: ﴿وَسَيَجۡزِي ٱللَّهُ ٱلشَّٰكِرِينَ﴾⟪3:144⟫ بما قبله؟\nقيل: إن ذلك قضية حذف بعضها، تقديرها: ومن أحسن يجزه الله.\nفإنه سيجزي الشاكرين."}];
